/* Denial library from Purview Gurukul (github.com/Purview-Healthcare/Purview-Gurukul), copied 2026-10-27.
   Each entry: name, codes (CARC), denial_wording, summary, questions to ask the payer, actions (next steps), keywords, family.
   Brahmastra uses it for the 'Suggested next steps' panel on a claim. Refresh it from Gurukul when the library changes. */
window.DENIAL_LIBRARY = [{"name":"Already paid to another provider","url":"https://www.arlearningonline.com/2024/10/b20-procedureservice-was-partially-or.html","codes":["B20"],"denial_wording":"Procedure/service was partially or fully furnished by another provider.","summary":"This hits when more than one provider billed the same service on the same date of service and the payer already paid someone else for it. First check whether that same service and DOS exists under a different provider inside your own system. If it does and the provider belongs to a different group, append modifier 77 and resubmit; if nothing is found on your side, appeal to the insurance or follow the client's instruction.","questions":["May I get the denial date?","What is the time frame to submit the corrected claim?","Could you please provide the name and NPI of the provider to whom the payment has been made?","What is the Fax# or Mailing address to send an appeal?","May I have the Claim# & call ref#?"],"actions":["Verify whether the same service on the same DOS exists under a different provider in your system","If found and the provider is from a different group, append modifier 77 and resubmit the claim","If the payer is Medicare, append modifier 77 and resubmit - a corrected claim is not needed","If the service is not found in your system and the paid provider is from a different group, send an appeal to the insurance","Follow client instructions"],"keywords":["already paid to another provider","paid to another provider","duplicate service another provider","service furnished by another provider","same DOS same CPT another provider","B20","modifier 77","repeat procedure by another physician"],"family":"Status & payment"},{"name":"Authorization absent or missing","url":"https://www.arlearningonline.com/2019/11/197-precertificationauthorizationnotifi.html","codes":["197","39","198"],"denial_wording":"Precertification/Authorization/Notification/Pre-treatment absent.","summary":"The payer required prior approval for the service and no authorization number was on file when the claim processed. Determine whether an auth actually exists (including one obtained on a related hospital claim for the same date of service), whether the service was an emergency and therefore exempt, or whether retro authorization is still obtainable. If none of those apply, the balance moves to appeal or to client instruction.","questions":["May I get the denial date?","Do you have Auth# on file?","I have the Auth#, Can you please reprocess the claim using this Auth#?","Is the place of service billed as 23 (Emergency) or not?","Could you please reprocess the claim since it is an emergency service & does not require Auth#?","Is there any hospital claim billed on same DOS where authorization# is present?","If the hospital claim for the same DOS has an Auth#, could you please use that Auth# and send the claim back for reprocessing?","Is it possible to obtain Retro Authorization#?","What is the procedure to obtain retro Auth#?","What is the time limit to send a corrected claim?","What is the Fax# or mailing address to send an appeal?","What is the time limit for appealing?","May I have the claim# & call ref#?"],"actions":["Reprocess claim with valid authorization number if available","Submit the corrected claim with proper authorization documentation","Request authorization number from payer system","Follow the procedure given by the rep to obtain Retro Authorization","Send an appeal to the insurance","Set the follow-up for the TAT","Work as per client instruction if no authorization pathway exists"],"keywords":["auth missing","no prior auth","precert not obtained","authorization not on file","denial 197","prior authorization denial","retro auth","pre-certification absent"],"family":"Authorization & referral"},{"name":"Bundled / Inclusive","url":"https://www.arlearningonline.com/2019/12/97-benefit-for-this-service-is-included.html","codes":["97"],"denial_wording":"The benefit for this service is included in the payment/allowance for another service/procedure that has already been adjudicated.","summary":"The payer considers this CPT to be part of another procedure it already paid on the same claim or same date, so it will not pay separately for it. Resolution depends on whether an NCCI edit actually exists between the two codes and whether an appropriate modifier can override that edit. If coding confirms the bundling is correct and no modifier applies, the balance is not collectible.","questions":["May I get the denial date?","To which CPT is it bundled with?","What is the time limit to send corrected claim?","What is the fax# or mailing address to send an appeal?","May I have the claim# and Call ref#?"],"actions":["Forward the claim to the coding team to assess whether resubmission with a modifier update is possible.","Use encoder tools to check whether an NCCI edit exists between the two procedures.","If the correct modifier is identified, update the claim and send a corrected claim to the insurance.","For Medicare, send a fresh claim instead of a corrected claim.","If no NCCI edit exists or coding confirms the billing is correct, call the insurance and ask them to reprocess the claim.","If the payer still denies after reprocessing is requested, send an appeal to the insurance.","If the CPT cannot be overridden with a modifier, the balance is not collectible."],"keywords":["bundled denial","inclusive to another procedure","CO-97","denial code 97","included in payment for another service","already adjudicated","NCCI edit denial","incidental procedure","modifier 59 needed","separate payment not allowed","payment included in allowance"],"family":"Coding & edits"},{"name":"Capitation / managed care","url":"https://www.arlearningonline.com/2019/12/24-charges-are-covered-under-capitation.html","codes":["24"],"denial_wording":"Charges are covered under a capitation agreement/managed care plan.","summary":"The payer billed (often Medicare or Medicaid) says the patient was enrolled in a managed care/capitated plan on the date of service, so that plan — not the billed payer — is responsible. Either the claim went to the wrong payer and must be redirected to the managed care plan, or the patient is not actually capitated and the denial is wrong. If the DOS truly falls inside the capitation contract period and the service is capitated, the balance is not collectible.","questions":["May I get the denial date?","Which managed care payer is active on the DOS?","Can I get the policy ID and claim mailing address for the managed care insurance?","May I know the start and end date of the capitation contract?","Does the DOS lie between the capitation contract start and end date?","May I get the processed and paid date?","What is the AA, PA and patient responsibility (coinsurance, deductible or copayment)?","May I know whether this patient is covered under capitation or not?","What is the TAT for reprocessing?","May I get the claim# and call ref#?"],"actions":["If managed care details are obtained, update the managed care insurance as primary and bill that plan.","Do not keep Medicare/Medicaid as secondary when billing the managed care plan.","If the patient is not covered under a capitation agreement, request the payer reprocess the claim.","If the DOS falls outside the capitation contract start/end dates, request reprocessing.","If the DOS lies within the capitation period and the patient is covered, the balance is not collectible."],"keywords":["charges covered under capitation agreement","CO-24","denial code 24","capitation denial","managed care plan denial","capitated agreement","HMO managed care responsible","Medicare Advantage capitation denial","patient enrolled in managed care","cap contract denial"],"family":"Eligibility & coverage"},{"name":"Charge exceeds fee schedule","url":"https://www.arlearningonline.com/2023/04/how-to-wok-on-denial-code-45.html","codes":["45"],"denial_wording":"Charge exceeds fee schedule/maximum allowable or contracted/legislated fee arrangement.","summary":"Code 45 is usually not a real denial: it is the difference between what you billed and the payer's allowed or contracted amount, which normally posts as a contractual adjustment. The key judgment is context. If the claim actually paid or applied to patient responsibility, the 45 amount is just the provider adjustment; if 45 shows up alongside other denial codes, work the other codes; and if 45 is the only reason with nothing paid, call the payer to confirm the real reason. PR-45 is the same logic but the balance is pushed to the patient, which typically happens for out-of-network providers.","questions":["What is the exact reason for this denial?","What is the contracted/allowable fee for this CPT code?","Was any payment applied to deductible, coinsurance, or copayment?"],"actions":["Scenario 1 - claim processed and paid or applied to patient responsibility: identify the denied amount as the provider adjustment and adjust it if you are authorized to do so","Scenario 2 - multiple denial reasons present: ignore the CO-45 and focus on resolving the other documented denials","Scenario 3 - CO-45 is the only denial reason: contact the insurance to confirm the exact denial reason and do not assume the amount is only an adjustment","For PR-45: follow the same three scenarios, but obtain client confirmation before billing the patient","Note that PR-45 typically occurs for out-of-network providers"],"keywords":["exceeds fee schedule","maximum allowable","allowed amount","contractual adjustment","contractual obligation","CO-45","PR-45","denial 45","over the allowable","charge exceeds contracted rate"],"family":"Status & payment"},{"name":"Claim applied towards deductible","url":"https://www.arlearningonline.com/2019/11/blog-post.html","codes":["1"],"denial_wording":"Deductible Amount - the fixed amount the policyholder must pay before the insurance begins paying for treatment.","summary":"The claim processed correctly but the allowed amount was applied to the patient's deductible, so the payer released nothing. This is patient responsibility (PR-1), alongside PR-2 coinsurance and PR-3 co-payment. Confirm the deductible limit and how much the patient has met including this claim, then decide whether the balance goes to a secondary payer or to the patient.","questions":["May I have the processed date?","What is the Allowed Amount (AA)?","How much is the total deductible limit on the policy?","How much has patient met including this claim?","Could you please fax the EOB? If not then mail it or provide the source to get the EOB?","What is the Turn around time (TAT) for reprocessing?","May I have the claim# & call ref#?"],"actions":["Once you receive the EOB through fax then note the account and send the EOB for posting","If the claim is sent back for reprocessing then you can set the follow-up for the TAT","Before billing the claim to a secondary or consecutive payer, verify the eligibility","If the patient policy is active for secondary or consecutive payers on DOS then rebill the claim","If no other payer is active or available on DOS then release the claim to the patient"],"keywords":["applied to deductible","deductible amount","PR-1","patient responsibility deductible","deductible not met","went to deductible","member owes deductible"],"family":"Status & payment"},{"name":"Claim in process","url":"https://www.arlearningonline.com/2019/11/claim-in-process-1.html","codes":[],"denial_wording":"The payer states the claim is still in process/pending, which happens when you call within the TAT or when the insurance needs additional information.","summary":"This is a status, not a denial - the claim is received and sitting in adjudication. Establish the received date, compute whether the payer is still inside its stated turnaround time, and find out whether processing is stalled waiting on documents from the provider or information from the patient. Follow-up timing and whether the balance can be released to the patient both depend on that answer.","questions":["When did you receive the claim?","What is the normal processing time or TAT?","What documents/info requested?","May I have the address or Fax# to send the document?","Is the claim waiting on information from the patient? If so, when was the letter sent to the patient?","May I get Claim# & Call ref#?"],"actions":["Calculate TAT from received date and check if it is within the TAT","If still within TAT, set the follow-up for the remaining days","If TAT is crossed and documents were requested from the provider, send the documents if available","If TAT is crossed, information was requested from the patient, and a letter was sent, wait for a month before releasing it to the patient","If it has been more than one month since the letter was sent, release the claim to the patient","If the rep cites a backlog, set the follow-up for the additional days quoted"],"keywords":["claim in process","claim pending","still processing","under review","in adjudication","TAT","turnaround time","additional information needed","development letter"],"family":"Status & payment"},{"name":"Claim is approved to pay","url":"https://www.arlearningonline.com/2019/11/approved-to-pay.html","codes":[],"denial_wording":"The payer states the claim is finalized to pay but the payment has not been released yet.","summary":"Adjudication is complete and the payer has committed to paying, but no check or EFT has gone out. Capture the processed date and the money breakdown (allowed, paid, patient responsibility) and confirm the release date. The main validation is that paid amount plus patient responsibility equals the allowed amount.","questions":["What is the processed date?","What are the allowed amount, paid amount and patient responsibility (Coins, Deductible, or Co-payment)?","When can we expect the payment?","May I have the claim# & Call ref#?"],"actions":["Verify that the sum of the paid amount and patient responsibility equals the allowed amount; if it does not, probe the representative for the correct information","Set the follow-up based on the expected payment timeline provided by the rep","Document the source of the status, insurance name/phone, representative name, processed date, financial amounts, timeframe, claim number and call reference number"],"keywords":["approved to pay","finalized to pay","payment not released","approved but not paid","check not issued yet","pending payment release"],"family":"Status & payment"},{"name":"Claim paid","url":"https://www.arlearningonline.com/2019/11/claim-paid.html","codes":[],"denial_wording":"The payer states the claim is paid, but the payment information has not been received or posted on the provider side yet.","summary":"The payer has released payment but it is not reflected in the practice's system. Pin down how the money moved - check versus EFT/credit card, single versus bulk - and whether it has actually cleared or been cashed. If the payment is stale (EFT uncleared past 7 days, check uncashed past 45 days) or went to a wrong address, push for a tracer or reissue.","questions":["What is the processed & paid date?","What are the allowed amount, paid amount and patient responsibility?","Was payment done through Check or EFT/Credit Card?","What is the check#?","What is the Transaction ID?","Was it Single check or Bulk check#?","What is the Bulk Amount?","May I have the check mailing address?","Is payment cleared?","May I have the encashment date?","Is paid date crossed 45 days?","Could you please fax the EOB?","May I have the claim# & Call ref#?"],"actions":["Document the insurance name, processed and paid dates, amounts, and payment method","Verify the check mailing address against the policy/provider records on file","For checks, confirm the encashment status and whether the 45-day threshold has passed","For EFT/credit card, confirm clearance allowing 2-3 days, maximum 7 days","Request the EOB by fax if the payment information is not available","If the payment is uncleared after 7 days or the check is uncashed after 45 days, request a reissue or a check tracer","If the check went to an incorrect address, request a W9 form or a new check"],"keywords":["claim paid","payment issued","check issued","EFT posted","payment not posted","missing payment","check tracer","reissue check","bulk check"],"family":"Status & payment"},{"name":"Claim paid and applied towards offset","url":"https://www.arlearningonline.com/2019/12/claim-paid-and-applied-towards-offset.html","codes":[],"denial_wording":"The claim was processed and paid but no payment was released because it was applied toward recovering a prior overpayment (offset/recoupment).","summary":"The insurance previously overpaid the provider, so instead of cutting a check on this claim they keep the money to recover that earlier excess payment. There is no denial code here because it is not a denial. The goal is to identify which prior patient/account the money was recouped against and get the EOB so the offset can be posted correctly.","questions":["May I get processed and paid date?","What are the allowed amount, paid amount and patient responsibility?","May I know the reason, why is it applied towards offset?","May I know to which patient is it applied towards offset?","May I know the patient account#, DOS & CPT?","Could you please fax the EOB?"],"actions":["If you receive the EOB then you can note the account and send the EOB for posting","If you do not receive the EOB then you can note the account","Take action as per your process update"],"keywords":["offset","recoupment","recouped","takeback","overpayment recovery","applied to prior overpayment","withheld payment","adjusted against previous overpayment"],"family":"Status & payment"},{"name":"Claim paid to patient","url":"https://www.arlearningonline.com/2019/11/100-payment-made-to-patientinsuredrespo.html","codes":["100"],"denial_wording":"Payment made to Patient/Insured/Responsible party.","summary":"The payer adjudicated and paid the claim, but sent the money to the patient/insured instead of the provider. This happens when the Assignment of Benefits (AOB) was not signed by the patient, or when the provider is out-of-network and the patient's plan does not cover out-of-network benefits. Because the provider never receives the funds, the balance goes directly to the patient.","questions":["What is the processed & paid date?","What are the allowed amount, paid amount and patient responsibility?","Why was the claim paid to patient?","May I have the claim# & call ref#"],"actions":["Verify sum of Paid Amount and Patient Responsibility equals the Allowed Amount","If the claim is paid to the patient then the claim can directly bill to the patient","Do not bill this denial to the secondary or consecutive payer","No need to ask for check details since it is not paid to the provider"],"keywords":["paid to patient","payment made to insured","payment made to responsible party","check went to the member","no AOB","assignment of benefits not signed","out of network paid to member","denial code 100"],"family":"Status & payment"},{"name":"Coverage terminated","url":"https://www.arlearningonline.com/2019/11/26-expenses-incurred-prior-to.html","codes":["27","26"],"denial_wording":"Expenses incurred after coverage terminated - the service is performed on a date that does not lie between the policy effective date and the policy termination date.","summary":"The date of service falls outside the window between the policy's effective date and its termination date, so the payer treats the patient as uninsured for that visit. Confirm the actual effective and term dates with the rep and compare them to the DOS. If the DOS really was covered the claim is sent back for reprocessing; otherwise the account moves to another active policy or to the patient.","questions":["What is the denial date?","What are the policy effective and termination dates?","Does the date of service fall within the active coverage period?","Is there another active policy available for the patient on the service date?","What is the turnaround time for reprocessing if coverage is reinstated?"],"actions":["If the DOS falls within the coverage period, request claim resubmission and set follow-up per the TAT provided","If another active policy exists on the DOS, update the policy ID and resubmit","If no active coverage exists, check for other insurance and verify eligibility if a secondary exists before releasing to the patient","Before releasing to the patient, confirm no other payers are available"],"keywords":["denial 27","CO 27","PR 27","coverage terminated","expenses incurred after coverage terminated","policy termed","inactive policy on DOS","denial 26 expenses incurred prior to coverage","patient not eligible on date of service"],"family":"Eligibility & coverage"},{"name":"CPT reached maximum allowance / frequency","url":"https://www.arlearningonline.com/2022/06/151-payment-adjusted-because-payer.html","codes":["151"],"denial_wording":"Payment adjusted because the payer deems the information submitted does not support this many/frequency of services.","summary":"The payer allows a CPT code only a limited number of times per day or per period, and the billed quantity/frequency exceeded that limit. The payer is not saying the service was unnecessary in principle, only that the documentation submitted does not justify billing it that many times. Resolution depends on whether the frequency limit was truly exceeded or the payer applied it in error.","questions":["May I get the denial date?","May I know the reimbursement guideline of the CPT (e.g., allowed once daily, twice daily)?","What is the allowed frequency?","Is the claim denied correctly based on your records?","Could you please send the claim back for reprocessing?","What is the turnaround time for reprocessing?","What is the time limit to send a corrected claim?","What is the time limit for appeals?","What is the fax number or mailing address for appeals?","May I have the claim number and call reference number?"],"actions":["Confirm the payer's reimbursement/frequency guideline for the CPT and whether the denial was applied correctly.","If denied correctly, follow client guidelines on next steps.","If denied incorrectly, request the payer send the claim back for reprocessing and note the turnaround time.","Verify in the system whether the same CPT was already paid on the same date of service.","Obtain the corrected-claim time limit and resubmit a corrected claim if applicable.","If the CPT is not found locally but the payer confirms payment, check whether the charge is unbilled or was posted under another provider at the facility."],"keywords":["CPT reached maximum allowance","denial code 151","CO-151","frequency limit denial","too many services billed","exceeds allowed frequency","units exceed maximum allowed","max units per day denial","number of services not supported","quantity billed exceeds limit"],"family":"Coding & edits"},{"name":"Date of death precedes date of service","url":"https://www.arlearningonline.com/2022/10/13-date-of-death-precedes-date-of.html","codes":["13"],"denial_wording":"Claim denied as the date of death precedes the date of service.","summary":"The payer's records show the patient died before the date of service billed on the claim, so it will not pay for a service supposedly rendered after death. Usually this is either a keying error in the date of service or an incorrect date of death on the payer's file. The fix depends on comparing the actual DOS against the payer's recorded date of death.","questions":["May I get the denial date?","May I get the date of death?","What is the TAT for reprocessing?","May I get the claim# and call ref#?","What is the fax# or mailing address to send an appeal?","How much is the appeal limit?"],"actions":["Get the date of death on file from the representative and compare it against the billed date of service.","If the DOS is before the date of death, request the payer reprocess the claim.","If the DOS is on the same date as the date of death, request the payer reprocess the claim.","If the DOS is after the date of death, gather the information per the rep's suggestion and file an appeal.","Validate the date of service from the medical records, and if it was updated incorrectly, make the correction."],"keywords":["date of death precedes date of service","denial code 13","patient deceased denial","DOD before DOS","patient died before service date","deceased patient claim denial","date of death on file wrong","expired patient denial"],"family":"Liability & other"},{"name":"Diagnosis inconsistent with patient age","url":"https://www.arlearningonline.com/2020/01/9-diagnosis-is-inconsistent-with.html","codes":["9"],"denial_wording":"Claim denied as the diagnosis code is inconsistent with the patient's age.","summary":"The ICD diagnosis code billed has an age restriction that conflicts with the patient's age on the payer's record. Typically it is either a coding selection error or bad date-of-birth data. Coding reviews the code and a corrected claim goes out, or an appeal is filed if the diagnosis was correct as billed.","questions":["May I get the denial date?","Could you please tell me which diagnosis code is invalid?","What is the time limit to send a corrected claim?","What is the TAT for reprocessing?","What is the Fax# or mailing address to send an appeal?","How much is the time limit to send an appeal?","May I have the claim# and call ref#?"],"actions":["Assign the denial to the coding team to review and provide the correct diagnosis code.","Submit the corrected claim once the coding response is received.","Send an appeal to the insurance if coding confirms the diagnosis code is correct.","Calculate the time limit from the denial date before sending the appeal.","Follow client preferences regarding submissions after the deadline."],"keywords":["diagnosis inconsistent with age","denial code 9","CO-9","ICD age edit denial","age restricted diagnosis","dx age mismatch","wrong DOB diagnosis denial","pediatric diagnosis on adult","age conflict ICD-10"],"family":"Coding & edits"},{"name":"Diagnosis inconsistent with patient gender","url":"https://www.arlearningonline.com/2020/01/10-diagnosis-is-inconsistent-with.html","codes":["10"],"denial_wording":"Claim denied as the diagnosis code is inconsistent with the patient's gender.","summary":"The ICD diagnosis code submitted is gender specific and conflicts with the gender the payer has on record for the patient. It stems either from an incorrect diagnosis code or from wrong gender/demographic data. Coding must review and supply the correct diagnosis code for a corrected claim, or the claim is appealed if the code is confirmed correct.","questions":["May I get the denial date?","Could you please tell me which diagnosis code is inconsistent?","Can you please reprocess the claim?","What is the TAT for reprocessing?","What is the Fax# or mailing address to send an appeal?","What is the time limit to send an appeal?","May I have the claim# and call ref#?"],"actions":["Assign this denial to the coding team to review and provide the correct dx code.","Submit the corrected claim to the insurance by updating the correct dx code.","Check the patient payment history to see whether the same DX code paid with the same CPT previously.","Send an appeal to the insurance if the coding team states that the dx code is correct.","Calculate the time limit from the denial date before sending the appeal."],"keywords":["diagnosis inconsistent with gender","denial code 10","CO-10","ICD does not match patient sex","dx gender mismatch","gender specific diagnosis denial","wrong sex on file denial","diagnosis sex edit","demographic gender error"],"family":"Coding & edits"},{"name":"Diagnosis invalid for date of service","url":"https://www.arlearningonline.com/2019/12/146-diagnosis-was-invalid-for-dates-of.html","codes":["146"],"denial_wording":"Diagnosis was invalid for the date(s) of service reported.","summary":"The ICD code submitted was not valid or active for the date of service billed, typically the result of an annual ICD-10 update where the code was deleted, expanded, or replaced. Check the code against the ICD-10-CM code set in force on the date of service, and pin down exactly which diagnosis code the payer is rejecting when several were submitted, then route it to coding. Depending on coding's answer, the fix is a corrected claim with a valid code or an appeal.","questions":["Which diagnosis code is invalid?","May I get the denial date?","If multiple diagnosis codes were submitted, which specific code(s) are problematic?","What is the time limit for payment on corrected claims?","What is the turnaround time for reprocessing?","What is the fax number or mailing address for appeals?","What is the appeal time limit from the denial date?"],"actions":["Check the diagnosis code against the ICD-10-CM code set for the date of service: codes change every October 1 (and sometimes April 1), so the code may have been deleted, replaced, or expanded to need more characters","Assign the denial to the coding team for review and a correction recommendation","Check payment history for the same diagnosis and procedure code on other dates of service in the same code year: if the payer paid those, ask it to reprocess, as the denial may be a payer error. A past payment does not prove the code is valid for this date of service","If coding confirms a correction is needed, resubmit a corrected claim within the allowable timeframe","If coding confirms the code is correct, send an appeal within the timeframe","Calculate the appeal deadline from the denial date before proceeding","Document the claim number, call reference, denial date, and insurance details"],"keywords":["CO-146","diagnosis invalid for date of service","invalid ICD-10 code","deleted diagnosis code","dx not valid for DOS","denial 11","diagnosis inconsistent with procedure","truncated diagnosis code"],"family":"Coding & edits"},{"name":"Duplicate claim","url":"https://www.arlearningonline.com/2019/11/18-exact-duplicate-claimservice.html","codes":["18","76","77"],"denial_wording":"Exact duplicate claim/service - the same service on the same date of service is billed more than once, or the claim is billed twice in error.","summary":"The payer sees this claim as an exact repeat of one it already has. Determine whether it is a true duplicate or a legitimate repeat service that differs by modifier, rendering provider, or exam time. If there is a real difference, push for reprocessing or submit a corrected claim/appeal with the appropriate repeat-procedure modifier; if everything matches, the extra charge is voided.","questions":["May I get the denial date?","What is the original status of the claim?","Can you please reprocess the claim since modifier, rendering provider or exam time on medical records are different?","What is the TAT for reprocessing?","What is the Fax# or Mailing address to send an appeal?","What is the time limit?","May I have the claim# & call ref#?"],"actions":["Verify whether the same CPT was billed multiple times on the same date of service","Compare modifiers, rendering providers and exam times across the charges","If differences exist and the rep agrees to reprocess, set the follow-up per the TAT provided","If the rep denies reprocessing, submit a corrected claim or an appeal","Add modifier 77 when the repeat service was by a different provider, and modifier 76 when it was a repeat by the same provider at a different exam time","For Medicare, submit a fresh claim rather than a corrected claim","If all details are identical, void the duplicate charge"],"keywords":["duplicate claim","exact duplicate","CO-18","OA-18","denial code 18","billed twice","already processed","repeat procedure","modifier 76","modifier 77"],"family":"Status & payment"},{"name":"Experimental or investigational","url":"https://www.arlearningonline.com/2022/11/55-proceduretreatmentdrug-is-deemed.html","codes":["55"],"denial_wording":"Claim denied as Procedure/treatment/drug is deemed experimental/investigational by the payer.","summary":"The payer has classified the billed procedure, treatment, or drug as experimental or investigational and therefore not a covered benefit. Start by checking whether that same CPT has ever been paid before by that insurance, then route the claim to the coding team to see whether an acceptable alternate CPT exists. If there is no alternate code, supply whatever documentation the payer asks for, or appeal if no documentation is needed.","questions":["May I get the denial date?","Can you please reprocess the claim as payment received for same CPT?","Do you need any additional document to process the claim?","What is the TAT for reprocessing?","What document is needed?","What is the Fax# or Mailing address to send an appeal?","How much is the time limit to send the document?","How much is the time limit to send an appeal?","May I have the claim# & call ref#?"],"actions":["Assign the claim to the coding team to obtain an alternate CPT code","If an alternate CPT is available, update the code and resubmit the claim","If no alternate CPT exists, follow the representative's suggestion","Share the additional documents if the insurance requests them","Consider filing an appeal if the insurance says no additional documentation is needed","Consult the client on the likelihood of payment for the CPT"],"keywords":["experimental","investigational","not FDA approved","unproven treatment","CO-55","denial 55","deemed experimental by payer","research procedure denial"],"family":"Coverage & medical policy"},{"name":"Globally inclusive to surgery","url":"https://www.arlearningonline.com/2019/12/globally-inclusive-to-surgery_97.html","codes":[],"denial_wording":"Denial as Globally inclusive to Surgery.","summary":"The payer considers the billed service to fall inside the global period of a previously performed surgery, so it is bundled into the surgical payment rather than paid on its own. Establish the main surgery date and the length of the global period, then determine whether the denied date of service actually falls inside that window. If it falls inside, a modifier is needed; if it falls outside, the payer should reprocess.","questions":["May I get the denial date?","When was the main surgery performed?","What is the Global period?","Could you please reprocess the claim (if DOS lies outside the global period)?","What is the TAT for reprocessing?","What is the time limit to send a corrected claim?","What is the Fax# or Mailing address to send an appeal?","How much is the time limit to send an appeal?","May I have the claim# & call ref#?"],"actions":["Determine whether the denied date of service falls within the global period range","If within the global period: send the claim to the coding team for an appropriate modifier","If a modifier is available: update the claim and resubmit","If no modifier is available: appeal or follow client instructions","If outside the global period: request reprocessing and set follow-up per the TAT provided"],"keywords":["globally inclusive","global package denial","included in global surgery period","post-op period denial","bundled into surgery","global surgical package","service within global days"],"family":"Coding & edits"},{"name":"Information requested from patient","url":"https://www.arlearningonline.com/2019/11/227-information-requested-from.html","codes":["227"],"denial_wording":"Information requested from the patient/insured/responsible party was not provided or was insufficient/incomplete.","summary":"The payer mailed the patient a questionnaire - typically coordination of benefits, other-insurance, or accident details - and either never got a reply or got an incomplete one, so it stopped processing the claim. Check whether the letter went out, when, and whether the patient responded. If the patient responded the claim is reprocessed; if not, at least 30 days must be allowed from the letter date before the balance is transferred to them.","questions":["When did you receive this claim?","May I get the denial date?","Have you sent letter to patient?","When did you send the letter to the patient?","What information have you requested from patient?","Have you received any response from patient?","Could you please reprocess the claim?","What is the TAT for reprocessing?","May I have the claim# & call ref#?"],"actions":["If the letter was sent, the patient responded, and the rep agrees to reprocess, set follow-up for the provided TAT","If the letter was sent within the last 30 days, do not bill the patient - allow a minimum of 30 days for a response","If the letter was sent and 30 or more days have passed with no response, release the claim to the patient","If no letter was sent, release the claim to the patient","Check payment history for nearby DOS showing another insurance as primary, verify eligibility, and update that plan as primary if active on the DOS","Resubmit the claim to the secondary insurance where applicable"],"keywords":["COB update needed","coordination of benefits denial","info requested from patient","patient did not respond to questionnaire","denial 227","other insurance information needed","accident questionnaire","member questionnaire not returned"],"family":"Liability & other"},{"name":"Information requested from provider","url":"https://www.arlearningonline.com/2019/11/226-information-requested-from.html","codes":["226"],"denial_wording":"Information requested from the Billing/Rendering Provider was not provided or not provided timely or was insufficient/incomplete.","summary":"The payer previously asked the provider for records or additional information and either never received it, received it late, or found what was sent incomplete. The claim is now denied pending that documentation. Whether it can still be saved depends entirely on the time limit measured from the denial date, so capture the deadline and the correct submission address on the call.","questions":["May I get the denial date?","What is the Fax# or Mailing address to send the MR?","How much is the time limit to send the records?","May I have the claim# and call ref#?"],"actions":["Calculate the time limit from the denial date; if it has not been crossed, send the medical records.","If the time limit has been crossed, follow client guidance on next steps.","Review the remark codes accompanying the denial, as they often clarify the exact information the payer wanted.","Document the source of status, insurance/clearing house details, and the mode used to send records (fax, mail, or website portal).","Record the final action taken: client assistance requested, appeal submitted, or medical records sent."],"keywords":["records not received","additional information not provided","denial code 226","CO-226","medical records requested","documentation not submitted timely","insufficient information denial","incomplete information","ADR denial","payer requested info from provider"],"family":"Liability & other"},{"name":"Invalid modifier on date of service","url":"https://www.arlearningonline.com/2019/12/182-procedure-modifier-was-invalid-on.html","codes":["182"],"denial_wording":"Procedure modifier was invalid on the date of service.","summary":"The modifier billed was not valid or active for that specific date of service, usually because of a code-set or effective-date change. Check whether the same CPT and modifier combination was paid before, then send the claim to coding for the modifier that was valid on that DOS. Resolution is either a corrected claim inside the filing window or an appeal timed from the denial date.","questions":["May I get the denial date?","Can you please reprocess the claim?","What is the time limit for payment received for same CPT & modifier?","What is the TAT for reprocessing?","What is the Fax# or Mailing address to send an appeal?","How much is the time limit to send an appeal?","May I have the claim# & call ref#?"],"actions":["Check patient payment history to see if the same CPT code paid with the same modifier","Assign to the coding team to review and provide the correct modifier","Submit a corrected claim once the proper modifier is received, if the time limit allows","If the coding team confirms the modifier is correct, send an appeal to the insurance","Calculate the appeal time limit from the denial date","For bilateral scenarios billed as an LT/RT split, void both lines and create a single line using modifier 50","For Medicare bilateral claims, send the void claim first, then a new claim with modifier 50"],"keywords":["CO-182","PR-182","modifier invalid on DOS","modifier not effective for date of service","deleted modifier","modifier expired","invalid modifier date of service"],"family":"Coding & edits"},{"name":"Invalid or missing CLIA number","url":"https://www.arlearningonline.com/2021/06/ma120missingincompleteinvalid-clia.html","codes":["MA120"],"denial_wording":"Missing/incomplete/invalid CLIA certification number.","summary":"Lab services require a valid CLIA certification number on the claim, and the payer either did not receive one or received one that does not match a valid certificate. The CLIA number belongs in box 23 of the claim form, and CLIA-waived tests must also carry the QW modifier. Resolution is to look up or obtain the correct CLIA number for the performing facility and resubmit a corrected claim.","questions":["May I get the denial date?","Do you show a CLIA number on the claim from box 23, or is it missing?","Is the CLIA number you have on file correct or not?","Can you provide the correct CLIA number you have on record for this facility?","What is the TAT for reprocessing?","What is the reason, if the claim will not be reprocessed?","May I have the claim# and call ref#?"],"actions":["Check box 23 of the claim form to confirm whether the CLIA number was submitted.","If the rep has provided the correct CLIA code then update it in your software or on the clearing house and resubmit the corrected claim.","Search for the CLIA number using the CDC portal at https://www.cdc.gov/clia/LabSearch.html or the CMS portal.","When there are multiple CLIA numbers under the same facility, try to match the address to identify the right one.","Bill CLIA-waived tests with the QW modifier along with the CLIA number."],"keywords":["missing CLIA number","invalid CLIA certification","MA120 denial","CLIA denial lab claim","box 23 CLIA","QW modifier denial","CLIA waived test billing","lab certification number missing","Clinical Laboratory Improvement Amendments denial","CLIA lookup"],"family":"Coding & edits"},{"name":"Invalid or missing NDC code","url":"https://www.arlearningonline.com/2021/05/m119missingincompleteinvalid.html","codes":["M119"],"denial_wording":"Missing/incomplete/invalid/deactivated/withdrawn National Drug Code (NDC).","summary":"The claim billed a drug HCPCS/CPT code but the National Drug Code was absent, incomplete, or no longer valid, so the payer cannot price the drug. NDC data belongs in the shaded portion of the line item on the CMS 1500 and must include the NDC units of measure and NDC units. The fix is to obtain the correct NDC, update it on the claim, and resubmit a corrected claim.","questions":["May I get the denial date?","Do you show an NDC number on the claim, and is it correct or not?","Can you provide the correct NDC number on file?","What is the time frame for reprocessing?","What is the reason, if the claim cannot be reprocessed?","What is the time frame to submit a corrected claim?","May I have the claim# and call ref#?"],"actions":["Verify the NDC code is present in the shaded portion of the line item, fields 24A-24G of the CMS 1500 form.","Confirm the NDC applies only to drug CPT/HCPCS codes, i.e. those starting with a letter such as J0256 or J2425.","Request the correct NDC from the representative, or search for the correct NDC independently.","Update the NDC along with the NDC units of measure and NDC units.","Resubmit the corrected claim once the NDC information is complete.","Escalate to the client if the complete NDC information cannot be obtained."],"keywords":["missing NDC denial","invalid NDC code","M119 denial","National Drug Code missing","NDC units of measure","J code NDC required","drug code denial","box 24 shaded area NDC","deactivated NDC","NDC not on file","injectable drug denial"],"family":"Coding & edits"},{"name":"Invalid place of service","url":"https://www.arlearningonline.com/2019/12/58-treatment-was-deemed-by-payer-to.html","codes":["58","5"],"denial_wording":"Treatment was deemed by the payer to have been rendered in an inappropriate or invalid place of service.","summary":"The POS code on the claim does not match where the payer believes the service was actually performed, or is not a valid setting for that CPT. Ask the rep for the correct POS and check whether a paid hospital claim exists for the same date of service, since the facility claim's POS reveals the true setting. The fix is a corrected claim with the right POS, or an appeal if coding stands by the original. Applies to physician billing, not hospital billing.","questions":["May I get the denial date?","Could you please provide the correct place of service?","Could you please check, is there any paid hospital claim associated on same DOS?","What is the POS in the hospital claim?","What is the time limit to send corrected claim?","May I have the claim# and call ref#?"],"actions":["Obtain the denial date and the correct POS from the representative","Check for an associated paid hospital claim on the same date of service","If the rep provides the correct POS, update and send a corrected claim (send fresh claims to Medicare, which does not accept corrected claims)","If the rep refuses to provide the POS, assign the claim to the coding team for POS review","Upon coding response, if coding confirms the POS is correct, contact the insurance to reprocess","If the rep still disagrees, request appeal details and submit the appeal"],"keywords":["CO-58","CO-5","invalid place of service","inappropriate place of service","POS code denial","procedure inconsistent with place of service","wrong POS billed","POS 11 vs POS 22"],"family":"Coding & edits"},{"name":"Level of service not supported","url":"https://www.arlearningonline.com/2024/01/150-payer-deems-information-submitted.html","codes":["150"],"denial_wording":"Payer deems the information submitted does not support this level of service.","summary":"The payer is saying the documentation on file does not justify the level of service that was billed. This is an umbrella denial with three usual root causes: the CPT has hit its maximum allowance for the time period, there is a medical necessity or coding problem, or medical records were requested. Always check the remark code first, and on the call push the rep for the exact issue, then follow the matching scenario.","questions":["May I know the exact issue?","What does the remark code indicate?","Is this a frequency issue, a medical necessity issue, or a records request?"],"actions":["Always check the remark code when working on this denial - sometimes the remark code provides the correct reason for denial","If the issue is that the CPT has reached the maximum allowance for a specific time period, follow the 151 frequency scenario","If the issue is medical necessity or a coding issue, follow the 50 medical necessity scenario","If medical records were requested, follow the 226 information-requested scenario"],"keywords":["level of service","does not support level of service","downcoding","documentation does not support","E/M level denial","CO-150","denial 150","denial 52","information submitted does not support"],"family":"Coverage & medical policy"},{"name":"Liability carrier","url":"https://www.arlearningonline.com/2019/12/20-this-injuryillness-is-covered-by.html","codes":["20"],"denial_wording":"This injury/illness is covered by the liability carrier.","summary":"The payer is saying the treatment was for an injury or illness that another party's liability insurance is responsible for, so the health plan is not the correct primary payer. The claim has to be redirected to the liability carrier as primary, or released to the patient if no liability information can be obtained. Once the liability carrier finishes and leaves a balance as patient responsibility, Medicare can be billed after the MSP code is updated.","questions":["May I get the denial date?","Could you please provide the liability carrier details?","Does the rep have the liability carrier details on file?","What is the name, policy ID, payer ID and mailing address of the liability carrier?","May I have the claim# and call ref#?"],"actions":["Update the liability carrier as the primary insurance and resubmit the claim.","Release the claim to the patient if liability insurance information is not available.","Check the system for existing liability insurance on file or prior patient payment history.","Check the payer web portal for liability carrier details if portal access is available.","Do not keep the commercial payer as secondary insurance.","If the liability carrier leaves the balance as patient responsibility, bill Medicare as secondary after updating the MSP code."],"keywords":["liability carrier denial","denial code 20","CO-20","injury covered by liability insurance","third party liability","TPL denial","slip and fall claim denial","accident related denial","MSP liability","Medicare secondary payer liability","bill the liability carrier first"],"family":"Liability & other"},{"name":"Maximum benefit exhausted","url":"https://www.arlearningonline.com/2019/11/119-benefit-maximum-for-this-time_28.html","codes":["119"],"denial_wording":"Benefit Maximum for this time period or occurrence has been reached.","summary":"The patient has used up the dollar amount or visit count the plan allows for this benefit within the applicable time period, so the payer will not pay this claim. Confirm whether the cap is measured in dollars or visits and how much was consumed excluding the claim in question. If the max is genuinely met the balance moves to the next payer or the patient; if it is not met, the payer is asked to reprocess.","questions":["What is the denial date?","Is the maximum benefit reached in terms of dollar amount or number of visits?","What is the allowed dollar amount or number of visits?","How much dollar amount/visits has the patient already met, excluding this claim?","Has the patient met the allowed amount excluding this claim?"],"actions":["If the patient HAS met the maximum excluding this claim, bill the claim to the secondary/consecutive payer after verifying eligibility","Do not change the payer sequence when billing secondary","If no secondary payer exists, release the claim to the patient","If the patient HAS NOT met the maximum excluding this claim, obtain the claim number and call reference number","Request the insurance reprocess and return the claim, then set follow-up per the provided turnaround time"],"keywords":["denial 119","CO 119","benefit maximum reached","max benefit exhausted","benefits exhausted","visit limit reached","dollar cap met","annual maximum met","no benefits remaining"],"family":"Eligibility & coverage"},{"name":"Medically not necessary","url":"https://www.arlearningonline.com/2019/12/50-these-are-non-covered-services.html","codes":["50","M25"],"denial_wording":"These are non-covered services because this is not deemed a medical necessity by the payer - remark M25: the information furnished does not substantiate the need for this level of service.","summary":"The payer decided the documentation or diagnosis submitted does not justify the service or the level of service billed. Coding review is the pivot point: if the diagnosis was wrong or incomplete, a corrected claim goes back; if coding confirms the original coding was right, the route is an appeal with supporting medical records. If an ABN was signed, the patient can be billed.","questions":["May I get the denial date?","What is the reason for medically not necessity?","Has payment been received for the same CPT & DX code previously?","What is the time limit to send a corrected claim?","What is the TAT for reprocessing?","What is the Fax# or Mailing address to send an appeal?","How much is the time limit to send an appeal?","May I have the claim# & call ref#?"],"actions":["Assign the claim to the coding team to review and provide the correct diagnosis code","If coding identifies an error, resubmit a corrected claim provided the time limit is not crossed","If coding confirms the coding is correct, submit an appeal with supporting documentation","Calculate the appeal time limit from the denial date before appealing","If an ABN was signed, bill the patient; if unsigned, adjust the claim"],"keywords":["not medically necessary","med nec denial","lack of medical necessity","denial 50","CO 50","M25","documentation does not support level of service","LCD NCD denial"],"family":"Coverage & medical policy"},{"name":"New vs established patient criteria","url":"https://www.arlearningonline.com/2021/04/new-patient-established-patient-codes.html","codes":[],"denial_wording":"Claim denied as new patient / established patient criteria not met.","summary":"The payer's records show the patient does not qualify for the E/M level billed, usually because a new patient code was billed for someone who had already received professional services from the physician or group within the past three years. A new patient is one who has not received any professional services from the physician within the past three years; an established patient has. Resolution is to verify the three-year service history, then either request reprocessing or recode.","questions":["May I get the denial date?","Can you confirm the patient's prior service history with this physician or group?","What prior date of service are you showing that makes this an established patient?","Can you reprocess the claim if no prior service is found on file?","What is the TAT for reprocessing?","May I have the claim# and call ref#?"],"actions":["Check the patient's historical dates of service in the software for the past three years.","Contact the insurance to confirm the service history if the history is unclear.","Request claim reprocessing if no prior professional service is found.","Assign to the coding team to select the correct CPT once the history is confirmed.","Do not change CPT codes without coding certification or client updates.","Apply the correct code set: new patient codes 99202-99205 and established patient codes 99211-99215."],"keywords":["new patient vs established patient denial","new patient criteria not met","three year rule E/M","99202 99203 99204 99205 denial","99211 99212 99213 99214 99215","established patient billed as new","E/M level denial","office visit new patient denied","patient seen within 3 years","same group same specialty new patient"],"family":"Coding & edits"},{"name":"No claim on file","url":"https://www.arlearningonline.com/2019/11/1.html","codes":[],"denial_wording":"The payer rep gives the status as \"no claim on file,\" meaning the insurance has no record of having received the claim.","summary":"The payer has no record of the claim, so nothing is in adjudication. The caller must first check the clearinghouse to see whether the claim was actually transmitted to the insurance or was rejected before reaching them. Resolution depends on whether the date of service falls inside the policy effective/termed dates and inside the timely filing limit.","questions":["May I have policy effective and termed date?","May I have the TFL?","Is there any other policy active for the patient on DOS?","May I have Policy ID, Policy effective and termed Date?","May I have claim mailing address, Payer ID and Fax#?","May I get call ref#?"],"actions":["Check the clearinghouse whether the claim was sent to insurance or it is rejected","Verify that the DOS falls within the policy effective and termed dates","Verify that the DOS falls within the timely filing limit (TFL)","If the details match system records, resubmit the claim via the correct payer ID","Always give priority to the submission of a claim via payer ID or Fax#","If TFL is crossed but proof of timely filing (POTF) is available, fax or mail the claim along with the proof","If there is no POTF and the claim was billed after TFL, the claim is not collectible"],"keywords":["no claim on file","NCOF","no record of claim","claim not received","claim not found in system","claim never got to the payer","not on file"],"family":"Status & payment"},{"name":"No-fault carrier / auto","url":"https://www.arlearningonline.com/2019/12/21-this-injuryillness-is-liability-of.html","codes":["21"],"denial_wording":"This injury/illness is the liability of the no-fault carrier / auto insurance.","summary":"The payer has determined the services relate to a motor vehicle or other no-fault accident, so the auto/no-fault carrier is primary rather than the health plan. The claim must be rebilled to the no-fault carrier as primary, or released to the patient if the auto insurance details cannot be obtained. Any balance the no-fault carrier leaves as patient responsibility can then go to Medicare after the MSP code is updated.","questions":["May I get the denial date?","Could you please provide the no-fault carrier / auto insurance details?","Does the rep have the details on file?","What is the name, policy ID and mailing address of the no-fault carrier / auto insurance?","May I have the payer ID?","May I have the claim# and call ref#?"],"actions":["Update that insurance as primary and resubmit the claim to the primary insurance.","Release the claim to the patient if the auto insurance information is not available.","Bill to Medicare after updating the MSP code when the no-fault carrier leaves a balance as patient responsibility.","Do not keep the commercial payer as secondary insurance."],"keywords":["no fault denial","denial code 21","CO-21","auto insurance denial","motor vehicle accident claim","MVA denial","PIP personal injury protection","car accident billing","no-fault carrier is primary","auto liability MSP"],"family":"Liability & other"},{"name":"Non-covered charges","url":"https://www.arlearningonline.com/2019/11/96-non-covered-charges.html","codes":["96"],"denial_wording":"Non-covered charges - either non-covered as per the patient's plan or non-covered as per the provider contract.","summary":"The service billed is not a benefit under the patient's plan, or it is excluded under the provider's contract with the payer. The first job on the call is to establish which of the two it is, because the resolution path is completely different: a patient-plan exclusion can often be routed to the patient or a secondary payer, while a provider-contract exclusion usually is not collectible. Diagnosis-driven non-coverage may be fixable by coding review and a corrected claim.","questions":["May I get the denial date?","Is it non-covered as per patient plan or provider contract?","What is the reason for non-covered?","What is the time frame to submit the corrected claim?","What is the fax# or appeal address to send the appeal?","How much is the appeal limit?","May I have the claim# and call reference#?"],"actions":["Send to coding team to review for alternative/correct diagnosis codes","Update and resubmit the corrected claim within the allowed time frame","Check payment history to see whether payment was received for the same CPT with the same provider from the same insurance","Verify secondary / consecutive payer eligibility and bill that payer if available","Release the balance to the patient if no other payer is available","Submit an appeal if applicable","Follow client instructions for provider-contract denials"],"keywords":["non covered charges","not a covered benefit","service not covered","plan exclusion","denial 96","CO 96","PR 96","benefit exclusion"],"family":"Coverage & medical policy"},{"name":"Non-covered — provider out of network","url":"https://www.arlearningonline.com/2019/11/96-non-covered-charges-provider-is-out.html","codes":["242","96"],"denial_wording":"Services not provided by network/primary care providers (Provider is Out of Network).","summary":"This denial occurs when the provider who rendered the service is not contracted with the insurance. Whether it is workable turns on the patient's plan type: PPO and POS plans normally carry out-of-network benefits, so the claim should be reprocessed. HMO and EPO plans generally do not, so the balance moves to a secondary payer or to patient responsibility.","questions":["May I get the denial date?","What plan does patient have? (HMO, PPO, EPO, POS)","Does patient plan cover out of network benefit?","Could you please reprocess the claim since patient plan does cover out of network benefit?","What is the TAT for reprocessing?","May I have the claim# and call ref#?"],"actions":["Verify the patient's plan type (HMO, PPO, EPO, or POS).","For PPO/POS plans with out-of-network coverage, request reprocessing and set follow-up per the TAT provided.","For HMO/EPO plans, bill to the secondary/consecutive payer or release the balance to the patient.","Before billing a secondary payer, verify the eligibility of the patient via the payer website or by phone.","If no active secondary payer exists, release the claim to the patient."],"keywords":["out of network denial","provider not contracted","non-covered charges","denial code 96","denial code 242","CO-96","OON benefits","not a network provider","services not provided by network provider","no in-network benefits","patient responsibility out of network"],"family":"Coverage & medical policy"},{"name":"Not covered by this payer / wrong contractor","url":"https://www.arlearningonline.com/2019/12/109-claimservice-not-covered-by-this.html","codes":["109"],"denial_wording":"Claim/service not covered by this payer/contractor. You must send the claim/service to the correct payer/contractor.","summary":"The claim went to a payer or contractor that has no responsibility for it, so it must be redirected to the correct carrier. Work out which insurance is actually on file and active for the date of service, then rebill there. If the primary has already paid, the account is handled under the primary EOB workflow instead.","questions":["May I get the denial date?","Which insurance is the primary insurance?","What is the effective and termination date of the policy?","Was the policy active on the date of service?","What is the policy ID, payer ID, and mailing address of the primary insurance?"],"actions":["Obtain primary insurance details from the representative or system records","Verify policy status on the date of service through the payer portal when available","Check for alternative coverage in the patient payment history if the rep lacks information","Resubmit to the primary insurance if the policy was active on DOS","Release to the patient if no active primary insurance exists or the policy is inactive","Update claim records with the correct primary/secondary insurance designations","If the primary insurance has already paid, follow the primary EOB scenario"],"keywords":["denial 109","CO 109","not covered by this payer","wrong contractor","send to correct payer","wrong MAC","claim sent to wrong insurance","payer not responsible"],"family":"Coordination of benefits"},{"name":"Other payer is primary","url":"https://www.arlearningonline.com/2019/12/22-this-care-may-be-covered-by-another.html","codes":["22"],"denial_wording":"This care may be covered by another payer per coordination of benefits.","summary":"The payer you billed believes it is not the primary insurance and that another carrier should pay first under coordination of benefits rules. Establish which policy is actually primary and whether it was active on the date of service. If a primary is confirmed, the claim is rebilled to that payer; if no other active coverage exists, the balance moves to the patient.","questions":["May I get the denial date?","Could you please tell me which insurance is the primary insurance?","What is the effective and termed date of the policy?","Was the policy active on the date of service?","What is the policy ID, payer ID, and mailing address of the primary insurance?"],"actions":["Determine whether the rep has the primary insurance details on file","Verify the policy was active on the date of service","If primary insurance details are available, update the records and resubmit the claim to the primary payer","If details are unavailable, check the system for other active insurance and verify eligibility through the payer web portal if accessible","If no active primary insurance is found, release the claim to the patient","If the primary has already paid, follow the primary EOB scenario","Obtain and document the claim number, call reference number, and turnaround time"],"keywords":["denial 22","CO 22","other insurance is primary","coordination of benefits denial","COB denial","bill primary first","wrong payer billed","care may be covered by another payer"],"family":"Coordination of benefits"},{"name":"Patient cannot be identified","url":"https://www.arlearningonline.com/2019/11/31-patient-cannot-be-identified-as-our.html","codes":["31"],"denial_wording":"Patient cannot be identified as our insured.","summary":"The payer searched its membership records with the patient demographics submitted on the claim and could not match them to an active member, so the claim was rejected without processing. This denial occurs when an incorrect patient name, date of birth, or gender is billed. It is a demographic/eligibility mismatch rather than a medical or coverage decision, so it is usually fixed by finding the correct member record and rebilling with corrected patient information.","questions":["Could you please search the patient with Name, DOB or Social Security#?","May I have the correct policy ID?","Could you please check if claim is available for the DOS with correct member ID?","May I have the effective and termed date of the policy?","May I have the Timely filing limit (TFL)?","May I have claim mailing address, Payer ID and Fax#?","May I get call ref#?"],"actions":["Search the patient using name, DOB, or SSN.","Verify the policy was active during the date of service.","Confirm the DOS falls within timely filing limits.","Resubmit the claim with corrected demographic information.","Release the balance to the patient if no other active insurance exists.","For Medicare: verify the correct MBI format and spelling.","For BCBS: confirm the 3-character alpha prefix is included."],"keywords":["patient cannot be identified as our insured","denial 31","CARC 31","member not found","patient not found in system","no member match","invalid member ID","wrong member ID","incorrect policy number","subscriber not found","not our member","demographic mismatch","wrong date of birth on claim","name mismatch with insurance","gender mismatch denial","missing BCBS alpha prefix","invalid MBI Medicare","eligibility not found for DOS"],"family":"Eligibility & coverage"},{"name":"Patient enrolled in hospice","url":"https://www.arlearningonline.com/2021/02/b9-patient-is-enrolled-in-hospice.html","codes":["B9"],"denial_wording":"Claim denied as patient enrolled in Hospice.","summary":"The patient was under a hospice election on the date of service, so the hospice agency - not the regular payer - is financially responsible for care related to the terminal condition. Pin down the hospice enrollment start and end dates and compare them to the DOS. If the DOS falls inside the enrollment period, the claim is rebilled to the hospice as primary; if it falls outside, the payer should reprocess.","questions":["May I get the denial date?","May I have the start date and end date of the hospice enrollment?","Does the date of service lie between hospice enrollment period?","Could you please send the claim back for reprocessing since patient not enrolled in hospice on DOS?","Can I get the hospice information such as hospice name, NPI, mailing address & policy ID?","What is the TAT for reprocessing?","May I get the Claim# & Call ref#?"],"actions":["If DOS is outside the hospice period, request the claim be sent back for reprocessing and set follow-up per the provided TAT","If DOS is within the hospice period, update the hospice as primary insurance and resubmit the claim to the hospice","Use the NPPES website to obtain hospice details if only the NPI is provided","Check the Medicare portal hospice tab for additional hospice information","For commercial insurance denials, bill to the hospice or Medicare if details are available and do not resubmit to the commercial payer","Use modifier GV when the attending physician is not employed by the hospice","Use modifier GW for services unrelated to the hospice condition"],"keywords":["hospice denial","patient on hospice","hospice election","terminal diagnosis billing","denial B9","GV modifier","GW modifier","bill hospice as primary"],"family":"Coverage & medical policy"},{"name":"Pre-existing condition","url":"https://www.arlearningonline.com/2019/12/51-these-are-non-covered-services.html","codes":["51"],"denial_wording":"These are non-covered services because this is a pre-existing condition.","summary":"The plan has a pre-existing condition waiting period and the payer says this date of service falls inside it, so the condition is excluded from coverage. The entire call turns on the exact start and end dates of that waiting period: if the DOS really falls inside it, the balance goes to the patient and should not be sent to a secondary payer; if the DOS falls outside it, the denial is wrong and the claim goes back for reprocessing.","questions":["May I get the denial date?","What are the start and end dates of the waiting period?","What is the TAT for reprocessing?","May I have the claim# & call ref#?"],"actions":["If the DOS falls within the waiting period, bill the claim to the patient and do not bill secondary / consecutive payers","If the DOS falls outside the waiting period, request the claim be sent back for reprocessing and set follow-up for the TAT","If the patient has other primary insurance, bill that insurance instead"],"keywords":["pre-existing condition","preexisting exclusion","waiting period denial","denial 51","PR 51","condition existed before coverage","pre-ex waiting period"],"family":"Coverage & medical policy"},{"name":"Primary EOB required","url":"https://www.arlearningonline.com/2019/12/163-attachmentother-documentation.html","codes":["163"],"denial_wording":"Attachment/other documentation referenced on the claim was not received.","summary":"The secondary payer processed the claim but never received the supporting attachment it needed, most commonly the primary payer's EOB. Confirm the current payer is truly secondary, obtain the primary payment details, and resend the EOB by the fax or mailing address the rep provides within the stated filing window. Check remark codes alongside the denial reason because they can point to a different required document.","questions":["May I get the denial date?","Which insurance is the primary insurance?","May I have the policy id, payer id and claim#?","What is the Fax# or mailing address and time limit to send the EOB?"],"actions":["Verify whether the current insurance is primary or secondary in your system","If secondary, follow up with the primary insurance and confirm payment was sent","Check CMS 1500 Box #29 (or UB 04 Locator #54) for primary payment details","Ask the rep to accept the primary EOB via fax or mail and send it within the specified timeframe","If the rep indicates the claim still has not been received, ask for the reprocessing turnaround time","If primary information is unavailable, check for alternate insurance or release the claim to the patient","Always verify remark codes against the denial reason, as they may require different resolution steps"],"keywords":["denial 163","primary EOB required","primary EOB not received","need EOB from primary","attachment not received","documentation not received","send EOB to secondary","explanation of benefits missing"],"family":"Coordination of benefits"},{"name":"Primary paid more than secondary allowed","url":"https://www.arlearningonline.com/2019/12/23-impact-of-prior-payers-adjudication.html","codes":["23"],"denial_wording":"The impact of prior payer(s) adjudication including payments and/or adjustment - this occurs when primary insurance already pays more or an equal amount to the secondary allowable amount.","summary":"The secondary payer compared the primary payer's payment against its own allowed amount and found the primary already paid at or above that allowable, so nothing further is owed. If the math checks out, the remaining balance is adjusted rather than appealed. If the primary payment is actually less than the secondary allowed amount, the claim should be sent back for reprocessing.","questions":["May I get the denial date?","What is the allowed amount? (secondary insurance)","Could you please reprocess the claim as primary paid amount is less than secondary allowed amount?","What is the TAT for reprocessing?","May I have the claim# and Call ref#?"],"actions":["Verify whether the primary paid amount exceeds or equals the secondary allowed amount","If yes, the balance is not collectible","If no, request reprocessing and set follow-up for the provided TAT","If the denial was received from the primary without payment, call the insurance and confirm the denial reason"],"keywords":["denial 23","OA 23","primary paid more than secondary allowed","prior payer adjudication","no secondary balance due","secondary allowable exceeded","impact of prior payer payment"],"family":"Coordination of benefits"},{"name":"Prior processing information incorrect","url":"https://www.arlearningonline.com/2022/03/how-to-work-on-denial-129-prior.html","codes":["129"],"denial_wording":"Prior processing information appears incorrect.","summary":"This denial comes from a secondary payer that cannot reconcile what the primary insurance did with the claim. It happens either because the primary never actually paid the claim, or because the primary's payment information was missing or wrong on the claim form sent to the secondary. The fix is to work the primary denial first, or to correct and resubmit the claim with accurate primary payment details in box 29 (CMS 1500) or locator 54 (UB-04).","questions":["Did the primary insurance pay this claim, and if not, what was the primary's denial reason?","Was the primary payment information received correctly on the claim you processed?","If this claim was paid before, was that payment recouped or reversed, and why?","Can the claim be reprocessed if the corrected primary payment information is supplied?","What is the fax number or mailing address to send the claim if it cannot be resubmitted electronically?","May I have the claim# and call ref#?"],"actions":["If the primary insurance did not pay the claim, work the denial received from the primary insurance first.","Note that the secondary may still pay certain denials such as non-covered charges depending on the policy benefit.","Check the claim form to see whether the primary payment information was sent correctly to the secondary insurance.","Verify the primary payment information at box# 29 on the CMS form or locator# 54 on the UB-04 form.","If the payment information is missing, resubmit the claim, and check the latest claim form to confirm the information now prints.","If the information is still missing after resubmission, send the claim through fax or the mailing address.","Connect with the insurance rep and verify the reason for the recoupment when payment has been reversed."],"keywords":["prior processing information appears incorrect","denial 129","CO-129","secondary claim denial primary payment","COB denial secondary","primary EOB info wrong","box 29 amount paid","locator 54 prior payments UB04","crossover claim denial","recoupment secondary insurance","MSP prior payer information"],"family":"Coordination of benefits"},{"name":"Procedure code invalid on date of service","url":"https://www.arlearningonline.com/2019/12/181-procedure-code-was-invalid-on-date.html","codes":["181"],"denial_wording":"Procedure code was invalid on the date of service.","summary":"The CPT/HCPCS code billed was not a valid, active code for the date the service was performed — typically because the code was deleted, replaced, or not yet effective in that code-set year. The payer is rejecting the code itself, not the service. The fix is to have coding identify the correct code for that DOS and rebill as a corrected claim, or appeal if coding confirms the original code was valid.","questions":["May I get the denial date?","Has this payer paid the same CPT code for other dates of service in the same code year?","Can you please reprocess the claim as a corrected claim?","What is the time limit for payment received for the same CPT?","What is the TAT for reprocessing?","What is the fax# or mailing address to send an appeal?","How much is the time limit to send an appeal?","May I have the claim# and call ref#?"],"actions":["Check the CPT/HCPCS code against the code set for the date of service: CPT changes every January 1 (Category III codes take effect six months after release) and HCPCS codes can change quarterly, so the code may have been deleted, replaced or not yet effective","Assign the claim to the coding team to review and provide the correct procedure code for that date of service.","Once the corrected CPT details are received, resubmit the corrected claim if the time limit permits.","If the coding team confirms the billed code is correct, send an appeal, calculating the appeal deadline from the denial date.","Note that some clients want a corrected claim submitted even if the time limit has been crossed, so work per client guidelines."],"keywords":["procedure code was invalid on the date of service","denial code 181","invalid CPT code","deleted CPT code denial","obsolete procedure code","code not valid for date billed","CPT not effective on DOS","invalid procedure code denial"],"family":"Coding & edits"},{"name":"Procedure code not paid separately","url":"https://www.arlearningonline.com/2019/12/234-this-procedure-is-not-paid.html","codes":["234"],"denial_wording":"Claim denied as procedure code is not paid separately.","summary":"The payer treats the billed CPT as a component of a primary procedure, so it carries no separate payment. Identify the primary CPT it rolls into and verify whether both codes were billed on the same claim form. If the codes went out on separate claims, a corrected claim or appeal is needed; if they were on the same claim and the code is separately billable, the payer should reprocess.","questions":["May I get the denial date?","Which is the primary CPT code?","What is the time limit to send a corrected claim?","What is the fax# or mailing address to send an appeal?","What is the TAT for reprocessing?","May I have the claim# and call reference#?"],"actions":["Verify whether both CPT codes appear on the same claim form","If the codes were billed together on one claim, request claim reprocessing","If the codes were billed separately, submit an appeal or a corrected claim","Assign to the coding team if the primary CPT code is unclear","Use encoding tools to verify the bundled status of the code","Contact the insurance to reprocess if the CPT can be billed independently"],"keywords":["not paid separately","CO-234","incidental to primary procedure","component code denial","no separate payment allowed","inclusive procedure denial"],"family":"Coding & edits"},{"name":"Procedure combination not compatible (NCCI)","url":"https://www.arlearningonline.com/2019/12/236-this-procedure-or-proceduremodifier.html","codes":["236"],"denial_wording":"This procedure or procedure/modifier combination is not compatible with another procedure or procedure/modifier combination provided on the same day according to the National Correct Coding Initiative or workers compensation state regulations/fee schedule requirements.","summary":"Two procedures billed on the same date of service hit an NCCI edit, so the payer treats one as bundled into the other and denies it. Find out which CPT the denied code was bundled to, then have coding check whether an NCCI override modifier is allowed. If coding confirms the billing is correct, the claim is pushed back for reprocessing or appealed.","questions":["May I get the denial date?","To which CPT is it bundled with?","What is the time limit to send corrected claim?","What is the fax# or mailing address to send an appeal?","May I have the claim# and Call ref#?"],"actions":["Route to the coding team to determine whether the claim can be resubmitted with a corrected modifier","Use encoder tools to identify NCCI edits between the procedures billed on the same date of service","If a modifier is found: update the claim and resubmit (send a fresh claim to Medicare)","If coding verifies the codes are correct: contact the payer to reprocess, and appeal if denied again"],"keywords":["NCCI edit denial","CCI bundling denial","denial 151","CO-236","procedure not compatible same day","column 1 column 2 edit","mutually exclusive procedures","needs modifier 59 or XU"],"family":"Coding & edits"},{"name":"Procedure inconsistent with modifier","url":"https://www.arlearningonline.com/2019/12/4-procedure-code-inconsistent-with.html","codes":["4"],"denial_wording":"The procedure code inconsistent with the modifier used or a required modifier is missing.","summary":"The modifier appended to the CPT does not match what the payer expects for that code, or a required modifier was never submitted. Confirm the denial date and appeal/corrected-claim timeframes, then route the claim to coding for the correct modifier. Payment history for the same CPT and modifier combination is useful leverage to demand reprocessing.","questions":["May I get the denial date?","What is the time limit to send a corrected claim?","What is the TAT for reprocessing?","What is the Fax# or Mailing address to send an appeal?","How much is the time limit to send an appeal?","May I have the claim# & call ref#?"],"actions":["Assign to the coding team to review and provide the correct modifier","Check patient payment history for the same CPT code billed with the same modifier","If the same code was previously paid, request reprocessing","If coding confirms the modifier is correct, send an appeal within the time limit","Calculate the appeal time limit from the denial date before sending the appeal","For bilateral claims billed with LT/RT modifiers, void both lines and resubmit using the bilateral modifier 50","For Medicare, void the paid claim first, then submit a new claim with the corrected modifier"],"keywords":["CO-4","modifier inconsistent with procedure code","required modifier missing","wrong modifier denial","invalid modifier combination","modifier 50 bilateral denial"],"family":"Coding & edits"},{"name":"Procedure inconsistent with patient age","url":"https://www.arlearningonline.com/2020/01/6-procedurerevenue-code-is-inconsistent.html","codes":["6"],"denial_wording":"Claim denied as the procedure/revenue code is inconsistent with the patient's age.","summary":"The CPT/revenue code billed carries an age restriction and does not match the patient's age on the payer's file. It usually means either the wrong age-banded procedure code was selected or the date of birth on record is incorrect. The fix is a coding review followed by a corrected claim, or an appeal if the original code was correct.","questions":["May I get the denial date?","What is the time limit to send a corrected claim?","What is the TAT for reprocessing?","What is the Fax# or mailing address to send an appeal?","How much is the time limit to send an appeal?","May I have the claim# and call ref#?"],"actions":["Assign the denial to the coding team to review and provide the correct procedure code.","Submit the corrected claim to the insurance by updating the correct CPT code.","Send an appeal to the insurance if coding confirms the billed code is correct.","Calculate the time limit from the denial date before sending the appeal."],"keywords":["procedure code inconsistent with age","denial code 6","CO-6","CPT age edit denial","age restricted procedure","wrong date of birth denial","DOB mismatch claim","pediatric adult code mismatch","age appropriate CPT","age related coding denial"],"family":"Coding & edits"},{"name":"Procedure inconsistent with patient gender","url":"https://www.arlearningonline.com/2020/01/7-procedurerevenue-code-is-inconsistent.html","codes":["7"],"denial_wording":"Claim denied as the procedure/revenue code is inconsistent with the patient's gender.","summary":"The CPT/revenue code billed is gender specific and does not match the gender the payer has on file for the patient. Either the patient's gender is wrong in the payer's records or on the claim, or the procedure code itself was coded incorrectly. Resolution is either a demographic correction, a coding correction, or an appeal if the code and gender are both already correct.","questions":["May I get the denial date?","Can you please reprocess the claim as payment was received for the same CPT?","What is the time limit to send a corrected claim?","What is the TAT for reprocessing?","What is the Fax# or mailing address to send an appeal?","How much is the time limit to send an appeal?","May I have the claim# and call ref#?"],"actions":["Update the correct gender and resubmit the claim.","Update the correct procedure code and resubmit the claim.","Route to the coding team when coding assistance is needed to confirm the correct procedure code.","Escalate to the client when client assistance is required.","Send an appeal and document the account as appeal sent.","Allow time when the payer has agreed to reprocess."],"keywords":["procedure code inconsistent with gender","denial code 7","CO-7","CPT does not match patient sex","gender mismatch denial","sex specific procedure denial","wrong gender on file","male female CPT edit","demographic mismatch denial","gender edit rejection"],"family":"Coding & edits"},{"name":"Procedure inconsistent with provider type / taxonomy","url":"https://www.arlearningonline.com/2019/12/8-procedure-code-is-inconsistent-with.html","codes":["8"],"denial_wording":"The procedure code is inconsistent with the provider type/specialty (taxonomy).","summary":"The payer is rejecting the CPT because it does not match the provider's type or specialty as identified by the taxonomy code. Confirm the rendering provider's specialty on NPPES using their NPI, confirm the taxonomy code is actually present on the claim (Box 24J for the rendering provider, Box 33b for the billing provider), and compare that specialty against the CPT billed.","questions":["May I get the denial date?","What is the exact reason for denial?","At which box# on claim form is taxonomy code missing?","Can you please reprocess the claim?","May I have the claim# & Call ref#?","What is the TAT for reprocessing?"],"actions":["Check the provider specialty on the NPPES website using the rendering provider's NPI","Verify whether the taxonomy code is present on the claim form - Box 24J for the rendering provider and Box 33b for the billing provider","Compare the provider specialty against the specialty required for the billed CPT code","If the specialty matches, request reprocessing and capture the claim# and call reference#","If the taxonomy code is missing, resubmit the claim to verify whether the code now appears","If the taxonomy exists on the CMS-1500 but the rep cannot locate it, resubmit the claim due to a potential transmission error","If the specialty mismatch persists after resubmission, escalate to the client for assistance"],"keywords":["taxonomy","taxonomy code missing","provider type specialty mismatch","procedure inconsistent with provider type","Box 24J","Box 33b","NPPES specialty","CO-8","denial 8","specialty does not match CPT"],"family":"Credentialing & provider"},{"name":"Provider not certified or eligible","url":"https://www.arlearningonline.com/2019/12/this-provider-was-not-certifiedeligible.html","codes":["B7"],"denial_wording":"This provider was not certified/eligible to be paid for this procedure/service on this date of service.","summary":"The payer is saying the provider tied to the claim was not credentialed, enrolled, or otherwise eligible to be paid for that specific service on that date. This is a routing denial: the actual fix depends on whether the problem sits with the rendering provider, the referring provider, or a provider type/specialty/taxonomy mismatch. Pin down which of those three the payer is citing before taking action.","questions":["May I get the denial date?","What is the exact issue - rendering provider, referring provider, or provider type/specialty?"],"actions":["Determine which of the three sub-scenarios applies, then follow that specific path.","Sub-scenario 1: the rendering provider is not eligible to perform the service billed.","Sub-scenario 2: the referring provider is not eligible to refer the service billed.","Sub-scenario 3: the procedure code is inconsistent with the provider type/specialty or the taxonomy code is invalid."],"keywords":["B7 denial","provider not certified","provider not eligible","not eligible to be paid for this procedure","credentialing denial","provider not enrolled","taxonomy code invalid","specialty mismatch denial","rendering provider not eligible","referring provider not eligible"],"family":"Credentialing & provider"},{"name":"Referral absent or missing","url":"https://www.arlearningonline.com/2020/02/288-referral-absent.html","codes":["288"],"denial_wording":"Claim denied as referral is absent or missing.","summary":"The payer denied because no referral from the patient's primary care physician was on file for this service. It matters most on HMO and POS plans, where a referral is a plan requirement; PPO and EPO plans usually should not require one. The fix is to find an existing referral number and get the claim reprocessed against it, or appeal if none exists.","questions":["May I get the denial date?","What plan does patient have? (HMO, PPO, EPO, POS)","Do you have referral# on file?","Is there any hospital claim billed on same DOS where referral# present?","If the hospital claim for the same DOS has a referral#, could you please use that referral# and send the claim back for reprocessing?","What is the turn around time?","What is the Fax# or mailing address to send an appeal?","How much is the time limit?","May I have the claim# and call ref#?"],"actions":["Check your own system first to see whether a referral number is available.","For HMO/POS plans where a referral number is available, request reprocessing and set follow-up per the TAT given.","For HMO/POS plans where the referral is found on the payer's own system, request reprocessing and set follow-up per the TAT.","For HMO/POS plans where no referral can be found, send an appeal or follow client instructions.","For PPO/EPO plans, get the payer to agree to reprocess and set follow-up per the TAT provided."],"keywords":["referral missing","no referral on file","referral absent","denial code 288","PCP referral required","HMO referral denial","referral number not found","missing PCP authorization","referral not obtained"],"family":"Authorization & referral"},{"name":"Referring provider not eligible","url":"https://www.arlearningonline.com/2019/12/183-referring-provider-is-not-eligible.html","codes":["183"],"denial_wording":"The referring provider is not eligible to refer the service billed.","summary":"The payer is refusing the claim because whoever is listed as the referring provider is not enrolled with, or not eligible to refer for, that service. Verify by checking whether that same referring provider has been paid before by this insurance, confirming the referring provider details in Box 17 and 17b of the CMS-1500, and looking the provider up on NPPES to see whether the specialty lines up with the billed CPT.","questions":["What is the denial date?","Do you have payment history from this same referring provider?","Why is the referring provider not eligible to refer these services?","Can you please reprocess the claim?","What is the TAT for reprocessing?","May I have the claim# & call ref#?","Is the referring provider enrolled with your insurance/group?","Does the referring provider's specialty match the service billed per the CPT code?"],"actions":["Check the insurance payment history for prior payments involving the same referring provider","Verify the referring provider information on the claim form in CMS-1500 Box 17 and Box 17b","Check the NPPES website for the referring provider's specialty","Confirm the specialty matches what the billed CPT code requires","Resubmit the claim if the referring provider information was missing or needed correction","Request that enrollment be completed if the referring provider is not enrolled with the payer","Obtain the correct referring provider details if the specialty does not match"],"keywords":["referring provider not eligible","ordering provider not eligible","referring physician not enrolled","Box 17 referring provider","PECOS enrollment","CO-183","denial 183","denial 185","ordering and referring denial"],"family":"Credentialing & provider"},{"name":"Revenue code and procedure code mismatch","url":"https://www.arlearningonline.com/2022/12/199-revenue-code-and-procedure-code-do.html","codes":["199"],"denial_wording":"Claim denied as revenue code and procedure code do not match.","summary":"On an institutional claim the revenue code billed on a line does not correspond to the CPT/HCPCS procedure code reported with it, so the payer rejects the line as an invalid combination. It is a coding/billing-format problem rather than a coverage problem. Fixing it means identifying the correct revenue code or CPT pairing and rebilling as a corrected claim, unless the payer applied the edit in error.","questions":["May I get the denial date?","Can you please reprocess the claim as payment was received for the same CPT and revenue code?","What is the TAT for reprocessing?","May I have the claim# and call ref#?","Can you suggest the correct revenue code or CPT code?","What is the time limit to send a corrected claim?","What is the fax# or mailing address to send an appeal?","How much is the time limit to send an appeal?"],"actions":["Check the patient's payment history for the same CPT and revenue code combination being paid previously.","If the same combination was paid before, request the payer reprocess the claim and note the reprocessing TAT.","If no prior payment exists, ask the representative to suggest the correct revenue code or CPT code.","Route the claim to the coding team to review and confirm the correct revenue code/CPT pairing.","Resubmit the corrected claim within the payer's corrected-claim time limit."],"keywords":["revenue code and procedure code do not match","denial code 199","rev code CPT mismatch","revenue code invalid for procedure","UB-04 revenue code error","rev code HCPCS mismatch","incorrect revenue code billed","procedure code not valid with revenue code"],"family":"Coding & edits"},{"name":"Routine services not covered","url":"https://www.arlearningonline.com/2019/12/49-this-is-non-covered-service-because_19.html","codes":["49"],"denial_wording":"This is a non-covered service because it is a routine/preventive exam or a diagnostic/screening procedure done in conjunction with a routine/preventive exam.","summary":"The payer classified the visit or procedure as routine, preventive, or screening, and that category is not a covered benefit under the patient's plan. The usual cause is a routine/screening diagnosis code driving the denial, so coding review comes first. If the coding is confirmed correct, the balance shifts to a secondary payer or to the patient.","questions":["May I get the denial date?","What is the time limit to send a corrected claim?","What is the Fax# or Mailing address to send an appeal?","How much is the time limit to send an appeal?","May I have the claim# & call ref#?"],"actions":["Assign to the coding team to review and provide the correct diagnosis code","Submit a corrected claim with the proper diagnosis code if the time limit is not crossed","If coding confirms the diagnosis is correct, bill to the patient or the secondary payer","Verify secondary / consecutive payer eligibility before billing","Send an appeal if within the time limit","Release the claim to the patient if no other payer is available"],"keywords":["routine exam not covered","preventive not covered","screening denial","annual physical denied","denial 49","PR 49","routine/preventive exclusion","wellness visit denied"],"family":"Coverage & medical policy"},{"name":"Secondary payment cannot be considered without primary","url":"https://www.arlearningonline.com/2019/12/ma04-secondary-payment-cannot-be.html","codes":["MA04"],"denial_wording":"Secondary payment cannot be considered without the identity of or payment information from the primary payer. The information was either not reported or was illegible.","summary":"The secondary payer cannot adjudicate because the primary payer's identity or payment data was missing or unreadable on the submitted claim. Locate the primary carrier's details, confirm the policy was active on the date of service, and correct the payer sequence before resubmitting. If no active primary coverage exists at all, the balance is released to the patient.","questions":["May I get the denial date?","Which insurance is the primary insurance?","Does the representative have primary insurance details?","What are the effective and termination dates of the primary policy?","Was the primary policy active on the date of service?","What is the primary insurance's policy ID, payer ID, and mailing address?"],"actions":["Verify whether primary insurance information is available in the system or the patient payment history","Check the payer web portal for primary insurance eligibility details","Confirm the primary policy was active on the date of service","Update the primary/secondary insurance designations in the billing system","Resubmit the claim to the primary payer","If no active primary insurance exists, release the claim to the patient","Document the claim number and call reference for follow-up"],"keywords":["MA04","MA 04 denial","secondary payment cannot be considered","no primary payment information","primary payer info missing","illegible primary information","COB info not reported","secondary claim denied missing primary"],"family":"Coordination of benefits"},{"name":"Timely filing expired","url":"https://www.arlearningonline.com/2019/11/29-time-limit-for-filing-has-expired.html","codes":["29"],"denial_wording":"The time limit for filing has expired.","summary":"The payer says the claim was received after its timely filing limit window closed. Compare the payer's claim receipt date against the TFL to see whether the claim was actually received on time and was denied in error, in which case it can be sent back for reprocessing. If it truly was late, the only path is an appeal with proof of timely filing - an initial claim to the same payer that was never received, an initially rejected claim, or initial billing to another payer.","questions":["May I get the denial date?","When did you receive the claim?","How much is the Timely filing limit?","Could you please send the claim back for reprocessing since the claim was received within TFL?","What is the TAT for reprocessing?","Can we appeal with POTF?","What is the fax# or Mailing address to send an appeal?","What is the appeal limit?","May I have the claim# & call ref#?"],"actions":["Verify whether the claim was received within TFL","If received within TFL and incorrectly denied, request reprocessing and set follow-up for the TAT","If POTF is available, send an appeal after confirming the appeal filing limit is not crossed","Calculate the appeal filing limit from the denial date and appeal only if within the limit","If no POTF is available, the claim is not collectible"],"keywords":["TFL expired","timely filing","filing limit exceeded","late claim submission","denial 29","CO 29","proof of timely filing","POTF appeal"],"family":"Timely filing"},{"name":"Workers Compensation","url":"https://www.arlearningonline.com/2019/12/19-this-is-work-related-injuryillness.html","codes":["19"],"denial_wording":"This is a work-related injury/illness and thus the liability of the Worker's Compensation Carrier.","summary":"The payer is saying the service treated an injury or illness that happened at work, so the Workers' Compensation carrier rather than the medical plan is financially responsible. Hunt for the WC coverage in your system, the patient's payment history, or the payer web portal, verify eligibility, then load WC as primary and resubmit there. If no WC information can be located at all, the claim is released to the patient.","questions":["May I get the denial date?","Could you please provide the worker compensation details?","What is the name, policy id, payer id & claim# & call ref#?","May I have the mailing address of worker comp?"],"actions":["Check the system for an existing WC insurance on file, or patient payment history indicating WC is primary","Check the payer web portal for WC insurance details if portal access is available","Verify eligibility for the WC insurance once identified","Update the WC insurance as primary and resubmit the claim to that payer","If WC information cannot be obtained, release the claim to patient responsibility","Do not keep the commercial payer on as secondary insurance","After WC processes, if a balance remains as patient responsibility, bill Medicare as secondary with the MSP code if applicable"],"keywords":["workers comp","workers compensation","work comp","WC carrier","on-the-job injury","work related injury","employer liability","CO-19","denial 19","WC primary"],"family":"Liability & other"},{"name":"EVV visit not verified or not matched","url":"https://www.medicaid.gov/medicaid/home-community-based-services/guidance/electronic-visit-verification-evv","codes":[],"denial_wording":"Claim denied because there is no matching Electronic Visit Verification (EVV) record for the visit.","summary":"Under the 21st Century Cures Act, Medicaid requires Electronic Visit Verification for personal care and home health care services that involve an in-home visit. The payer compares each claim with the verified EVV visit on member ID, provider Medicaid ID, procedure code and modifier, date of service and number of units. If there is no verified visit, or any of those details do not match, the claim is denied. The fix is made in the EVV system first, and then the claim is resubmitted.","questions":["May I get the denial date?","Is the EVV visit missing, or did a detail not match: member ID, provider ID, procedure code or modifier, date of service, or units?","Do you show a verified EVV visit for this member on this date of service?","How many units does the EVV visit show?","Once the visit is corrected, do we resubmit the claim or can you reprocess it?","What is the time limit to resubmit?","May I have the claim# & call ref#?"],"actions":["Look up the visit in the EVV portal for the DOS and check that it is in verified status","If the visit is missing or has exceptions, have the client or agency add or fix it in the EVV system","Compare member ID, provider ID, procedure code and modifier, DOS and units on the claim against the verified visit","Billed units must be the same as or less than the EVV units","If the claim has the wrong details, correct the claim to match the verified visit","Resubmit the claim only after the visit shows as verified, and set a follow-up","If no visit can be verified, take client assistance"],"keywords":["EVV","electronic visit verification","EVV denial","visit not verified","EVV mismatch","home health visit verification","personal care EVV","no EVV record"],"family":"Coding & edits"},{"name":"Manufacturer invoice requested","url":"https://med.noridianmedicare.com/web/jeb/topics/claim-submission/reason-code-guidance/missing-invoice","codes":["252","M23"],"denial_wording":"An attachment/other documentation is required to adjudicate this claim/service. Missing invoice.","summary":"The payer cannot price the item without the invoice. This is common for DME, supplies, drugs and unlisted or miscellaneous codes that have no fee schedule amount. For Medicare the denial comes as CO-252 with remark M23, usually because the invoice price is missing, is in the wrong format, or more than one price was sent. Medicare wants the total invoice price plus shipping in Item 19 of the CMS-1500 or its electronic equivalent, and the fix is to resubmit the claim, not appeal. Other payers may ask for a copy of the manufacturer or supplier invoice.","questions":["May I get the denial date?","Which line item or code needs the invoice?","Do you need the invoice price on the claim, or a copy of the invoice?","If a copy of the invoice is needed, how should we send it: fax, portal upload or with a corrected claim?","What is the fax# or mailing address, and what should we reference?","What is the time limit to resubmit or send the invoice?","What is the TAT for reprocessing?","May I have the claim# & call ref#?"],"actions":["Identify the line item the payer needs the invoice for","Get the manufacturer or supplier invoice from the client","For Medicare, enter the total invoice price plus shipping in Item 19 or its electronic equivalent. Do not include handling or other fees","Enter one price only, in the correct dollar format, with nothing else besides the description of an unlisted code if required","Resubmit the claim. This denial cannot be appealed with Medicare, but the claim can be resubmitted with corrected information","For other payers, send a copy of the invoice the way the payer confirmed, with the claim number","If the client cannot provide the invoice, take client assistance"],"keywords":["manufacturer invoice","manufacturing invoice requested","missing invoice","invoice required","M23","invoice for pricing","DME invoice","unlisted code invoice","supplier invoice"],"family":"Coding & edits"},{"name":"Medicare Part B deductible not covered by secondary","url":"https://www.medicare.gov/publications/02110-medigap-guide-health-insurance.pdf","codes":[],"denial_wording":"The secondary plan does not cover the Medicare Part B deductible.","summary":"Medicare applied the charge to the patient's annual Part B deductible and the claim crossed over to the secondary plan. Most Medicare Supplement plans do not pay the Part B deductible. Only Plans C and F cover it, and supplement plans sold to people new to Medicare on or after January 1, 2020 are not allowed to cover it. When the secondary confirms the Part B deductible is not a benefit under the patient's plan, the amount is patient responsibility unless another payer is on file.","questions":["May I get the denial date?","Which plan does the patient have, and is the Part B deductible a covered benefit under it?","Did you receive the Medicare EOB with the claim?","How much patient responsibility are you showing?","Is there any other active coverage on file for this patient?","May I have the claim# & call ref#?"],"actions":["Check the Medicare EOB to confirm the amount was applied to the Part B deductible","Confirm with the secondary that the Part B deductible is not a covered benefit under the patient's plan","If the secondary denied in error or did not have the Medicare EOB, send the EOB and request reprocessing","Check for another payer such as Medicaid and bill it if available","If no other coverage, move the balance to patient responsibility or follow client instructions"],"keywords":["Part B deductible not covered","secondary does not cover Part B","medigap","Medicare supplement plan","crossover to secondary"],"family":"Coordination of benefits"},{"name":"Vision benefit not eligible: exam or materials","url":"https://www.vspprm.com/dam/jcr:05d28663-0598-49b1-a14d-d1fcdc156ba3/PRM_Print_01012024.pdf","codes":[],"denial_wording":"Member has no exam and/or materials benefit available for this visit.","summary":"Vision plans allow an exam, lenses, frame or contacts only once in a set period. Covered eye exams are generally available once every 12 or 24 months, counted on a service year, calendar year or fiscal year. Eligibility is confirmed by pulling an authorization before the visit, which shows what the patient is currently eligible for and is usually valid for 30 days. The claim denies when the patient already used the benefit, the plan does not include it, or the claim does not match a valid authorization. It can be for the exam only, the materials only, or both.","questions":["May I get the denial date?","Is the patient not eligible for the exam, the materials, or both?","What is the benefit frequency for exam, lenses, frame and contacts, and how is the period counted?","When was each benefit last used, and what is the next eligible date?","Was an authorization issued for this DOS, what did it cover, and when did it expire?","Does the patient have any other vision or medical coverage on file?","May I have the claim# & call ref#?"],"actions":["Check whether an authorization was pulled before the visit and whether it was still valid on the DOS","Check that the authorization number and the services billed match what was authorized","Verify the benefit frequency and when each benefit was last used","If the patient was eligible and the claim was denied in error, request a claim correction or reprocessing","If the patient has another vision plan or the exam was medical, coordinate benefits and bill that plan","If the benefit was already used, bill the patient or follow client instructions"],"keywords":["not eligible for exam","not eligible for materials","not eligible for exam and materials","vision benefit used","frequency limit vision","eye exam not eligible","frames lenses not eligible","vision eligibility"],"family":"Eligibility & coverage"},{"name":"Payer refused to share claim details","url":"","codes":[],"denial_wording":"The claim is processed but the payer representative will not release the EOB or claim details.","summary":"This is not a true denial. The claim has been processed or paid, but the rep will not fax, mail or read out the EOB. Typical reasons are that the EOB is only available on the portal, the provider is set up for electronic remits, or the caller could not be verified. The claim cannot be posted or worked further without the EOB, so the next step is another route to get it.","questions":["May I get the processed date, paid amount, check or EFT number and paid date?","Can you fax or mail a copy of the EOB?","If you cannot fax or mail the EOB, where can we get it: provider portal, ERA or clearinghouse?","Which address or ERA setup did the original EOB go to?","Can you at least give the allowed amount, patient responsibility and denial reason per line?","May I have the claim# & call ref#?"],"actions":["Note every detail the rep is willing to share: paid amount, check or EFT number, paid date","Check the payer portal for the EOB","Check the clearinghouse or ERA for the remit","If portal access is not available, request access or take client assistance","Send a written or fax request for the EOB if the payer accepts one","Set a follow-up and call back to try another representative"],"keywords":["refused to provide EOB","refused EOB","rep refused","payer will not release","need portal access","available on portal only"],"family":"Status & payment"},{"name":"UCHP plan (University of Chicago Health Plan)","url":"https://bpb-us-w2.wpmucdn.com/voices.uchicago.edu/dist/d/793/files/2024/07/uchp-provider-manual-7.1.24.pdf","codes":[],"denial_wording":"Claim denied because the patient is covered under the University of Chicago Health Plan (UCHP).","summary":"UCHP is the University of Chicago Health Plan, a self-insured plan for employees of the University of Chicago and the University of Chicago Medical Center and their families. Aetna handles customer service, medical management and claims processing. Care is coordinated through the member's primary care physician, and covered treatment is provided at University of Chicago Medicine facilities and by UCHP designated providers. Services from other facilities or providers are not covered unless they were pre-certified. Claims first submitted more than 90 days after the service are not paid.","questions":["May I get the denial date and the exact denial reason?","Is the rendering provider a UCHP designated provider?","Was pre-certification or a PCP order required for this service, and is one on file?","When did you receive the claim, and was it within the 90 day filing limit?","What is the process and time limit to appeal?","May I have the claim# & call ref#?"],"actions":["Confirm the patient's plan is UCHP and coverage was active on the DOS","Check whether the provider is a University of Chicago Medicine or UCHP designated provider","Check for pre-certification or a PCP order for this DOS","If pre-certification exists, send it with an appeal as explained in the denial letter","Check that the claim was first submitted within 90 days of the DOS and keep proof of timely filing","Confirm the claim went to UCHP Claims Department c/o Aetna, PO Box 981106, El Paso, TX 79998-1106 or electronically through Aetna. If not, correct and resubmit","Do not bill the member for covered services that UCHP denied. Take client assistance"],"keywords":["UCHP","UCHP plan","University of Chicago Health Plan","UCHP referral","UCHP out of network","UCHP authorization"],"family":"Authorization & referral"},{"name":"W-9 form requested","url":"https://www.irs.gov/instructions/iw9","codes":[],"denial_wording":"Claim denied or pended because the payer needs a current W-9 (W9) form for the billing provider.","summary":"A W-9 is the IRS form a provider uses to give a payer its correct name and Taxpayer Identification Number. Payers keep it on file to set up and pay the billing provider. The claim denies or pends when the payer has no W-9 on file, or when the Tax ID, name or address on the claim does not match its records. Payers do not accept a Tax ID or address change through the claim form, so the change has to be sent on a W-9. Once the provider record is updated, the claim usually needs to be reprocessed or resubmitted.","questions":["May I get the denial date?","What do you have on file for the billing provider's Tax ID, name and address?","Which detail on the claim does not match your records?","Where should the W-9 be sent: fax, email or portal?","How long does the provider record update take?","After the update, will you reprocess the claim or do we need to resubmit?","May I have the claim# & call ref#?"],"actions":["Compare the Tax ID, billing name, NPI and address on the claim with the client's current W-9","If the claim was billed with wrong provider details, correct and resubmit","Get the current signed W-9 from the client","Send the W-9 to the payer by the method confirmed, with the claim number","Set a follow-up for the provider record update","Once updated, request reprocessing or resubmit the claim"],"keywords":["W9","W-9","W9 form","W-9 form requested","denied for W9","tax ID not on file","TIN mismatch","update provider information","W9 required","W9 denial","W9 request","W9 missing","W9 not on file"],"family":"Credentialing & provider"},{"name":"Patient in a Skilled Nursing Facility stay","url":"https://www.cms.gov/medicare/coding-billing/skilled-nursing-facility-snf-consolidated-billing","codes":["190"],"denial_wording":"Payment is included in the allowance for a Skilled Nursing Facility (SNF) qualified stay.","summary":"On the date of service the patient was in a Medicare covered Skilled Nursing Facility stay. Under SNF consolidated billing, payment for most services during the stay is bundled into the payment Medicare makes to the SNF, so outside providers cannot bill Part B separately and must look to the SNF for payment. A few services are excluded and can still be billed separately, including physician professional services, certain dialysis and ambulance services, certain chemotherapy drugs and their administration, radioisotope services and customized prosthetic devices.","questions":["May I get the denial date?","What are the SNF admission and discharge dates?","What is the name, NPI and phone number of the facility?","Was the patient in a covered Part A stay on this date of service?","Is this service excluded from SNF consolidated billing?","May I have the claim# & call ref#?"],"actions":["Confirm in eligibility that the patient was in a covered SNF stay on the DOS","If the DOS is outside the stay dates, request reprocessing","Check whether the service is excluded from SNF consolidated billing","If it is a physician professional service, bill only the professional part to Part B and resubmit","If the service is included in the SNF payment, look to the facility for payment or take client assistance","Do not bill the patient for services included in the SNF payment"],"keywords":["skilled nursing facility","SNF","SNF consolidated billing","patient in SNF","SNF stay","CO 190","denial 190","facility responsible","part A stay"],"family":"Liability & other"},{"name":"Readmission for same diagnosis / DRG","url":"https://www.cms.gov/regulations-and-guidance/guidance/manuals/downloads/clm104c03.pdf","codes":[],"denial_wording":"This admission is denied or bundled as a readmission for the same diagnosis (DX) or Diagnosis-Related Group (DRG) within the payer's readmission window (often 30 days) of a prior inpatient or outpatient stay.","summary":"The payer treats the second admission as part of the same episode of care as the first — because it is the same DX (diagnosis) or DRG (the payment group a hospital stay falls into) and it happened inside the payer's readmission window (commonly 30 days). It won't pay the second stay separately, both to avoid paying twice for one episode and to discourage premature discharge. Resolution depends on whether the readmission is truly related: if it is unrelated, or falls under an exclusion in the payer's readmission policy (for example some planned or staged treatments, or a transfer), it may still qualify for separate payment and can be appealed with records. A readmission for a complication of the first stay is usually treated as related. If it is a genuinely related readmission inside the window, it is usually bundled into the first stay and not separately collectible.","questions":["May I get the denial date?","Which prior claim number and date of service is this readmission being linked to?","What readmission window are you applying (for example 30 days)?","Is a reconsideration or appeal with medical records allowed, and what is the time frame?","What is the fax# or mailing address to send an appeal, and may I have the claim# and call ref#?"],"actions":["Pull both the prior admission and this admission and confirm whether they are the same DX (diagnosis) or DRG and fall within the payer's readmission window.","Check the payer's readmission policy for exclusions (for example unrelated conditions, some planned or staged treatments, transfers); a complication of the first stay is usually treated as related.","If it is unrelated or an exclusion applies, send an appeal with medical records showing it is a distinct, separate episode of care.","For Medicare, a same-day readmission to the same hospital for a related condition is combined with the first stay on one claim; an unrelated same-day readmission is billed separately with condition code B4.","If it is a genuinely related readmission inside the window, the second stay is likely bundled into the first DRG and the balance is not collectible."],"keywords":["readmission denial","same diagnosis readmission","same DRG","30 day readmission","readmission within window","bundled readmission","inpatient readmission","related readmission","planned readmission exception","readmission bundled into prior stay"],"family":"Coding & edits"},{"name":"Vision plan vs. medical plan: which pays first","url":"https://x12.org/codes/claim-adjustment-reason-codes","codes":["22"],"denial_wording":"This care may be covered by another payer per coordination of benefits — the rules that decide which of a patient's plans pays first (primary) and which pays second (secondary).","summary":"When a patient has more than one plan — for example a medical plan and a vision plan (VSP, EyeMed) — COB (Coordination of Benefits) rules decide the order the plans pay in. A common eye-care example: refraction (CPT 92015 — the eye-measurement test for glasses) is often not a medical benefit, so if medical denies it or applies it to the patient, it can be coordinated to the vision plan; and some plans (such as VSP Essential) can coordinate a normal medical COB. Resolution is to confirm which plan is primary vs. secondary, bill the correct payer first, and then send the primary's EOB (Explanation of Benefits — the payer's statement of what it paid) to the secondary.","questions":["May I get the denial date?","Which other carrier do you show on file, and is that plan primary or secondary to you?","Do you need the other payer's EOB (Explanation of Benefits) to process this claim?","What is the timely filing limit to bill the correct payer?","What is the fax# or mailing address, and may I have the claim# and call ref#?"],"actions":["Verify the patient's active coverages and the correct primary/secondary order (call the insurance or check eligibility).","If another plan is primary, bill that plan first; once it pays, send its EOB (Explanation of Benefits) to the secondary payer.","For vision-specific services such as refraction (CPT 92015), route the charge to the vision plan (VSP, EyeMed) per the plan's rules.","If the payer's COB order on file is wrong, have the member or payer submit a COB update, then resubmit.","If both payers deny as 'the other is primary,' obtain a COB update from the member/payer to break the loop before resubmitting."],"keywords":["vision vs medical cob","vision plan cob","medical vs vision insurance","vision cob","VSP","EyeMed","VSP Essential","refraction 92015","refraction denied by medical","eye exam cob"],"family":"Coordination of benefits"},{"name":"Downcoded to a lower level of service","url":"https://www.cms.gov/outreach-and-education/medicare-learning-network-mln/mlnproducts/downloads/eval-mgmt-serv-guide-icn006764.pdf","codes":[],"denial_wording":"The payer reprocessed the claim at a lower level of service than billed (downcoding) — for example paying a billed higher-level visit as a lower-level one — stating the documentation or criteria did not support the level submitted.","summary":"The payer agrees the service happened but pays for a lower-complexity code than was billed — for example a level-4 E/M (Evaluation and Management, i.e. an office/visit code) billed but paid as a level-3 — so the allowed amount drops. This is often driven by automated edits or a documentation review. Resolution is to compare what was billed vs. what was paid, confirm whether the documentation (time or medical decision-making) supports the billed level, and if it does, appeal with the records; if it does not, the lower level may be correct.","questions":["May I get the denial date?","Which code did you downcode it to, and what was the reason?","Was this an automated edit or a documentation review?","Can medical records be submitted for reconsideration, and what is the time frame?","What is the fax# or mailing address, and may I have the claim# and call ref#?"],"actions":["Compare the billed CPT (procedure code) / level against the paid code/level shown on the EOB (Explanation of Benefits).","Send to the coding team to confirm whether the documentation (time or medical decision-making) supports the level that was billed.","If the records support the billed level, appeal with the office/progress notes attached.","If the records do not support the higher level, accept the downcode or submit a corrected claim with the right level.","Track repeated downcoding by payer and route it to provider education / coding review."],"keywords":["downcoding","downcoded claim","level of service reduced","E/M downcode","paid at lower level","documentation does not support level","reduced to lower CPT","coding downgrade","reprocessed lower level"],"family":"Coding & edits"},{"name":"Inpatient downgraded to observation / outpatient","url":"https://www.cms.gov/regulations-and-guidance/guidance/manuals/downloads/clm104c01.pdf","codes":[],"denial_wording":"The payer determined the stay did not meet inpatient criteria and downgraded (reclassified) the inpatient admission to observation or outpatient status, which pays at a much lower rate.","summary":"After a utilization or clinical review, the payer decides the patient's condition did not meet inpatient medical-necessity criteria (for example InterQual or MCG guidelines), so it reclassifies the stay from inpatient to observation (outpatient) — which greatly reduces payment. Resolution is to review the clinical documentation against the payer's criteria: if inpatient was justified, appeal (a peer-to-peer or a written clinical appeal) with records; if it was not, rebill the encounter correctly as observation/outpatient. For Medicare (and Medicare Advantage plans since 2024) the Two-Midnight rule guides inpatient status; if the hospital's own utilization review changes the status before discharge, with the physician's agreement, the stay is billed as outpatient with Condition Code 44.","questions":["May I get the denial date?","Which criteria set did you apply (for example InterQual or MCG)?","Is a peer-to-peer review available, and what is the window to request it?","Is a written clinical appeal allowed, and what is the time frame?","What is the fax# or mailing address, and may I have the claim# and call ref#?"],"actions":["Pull the clinical documentation and compare it against the payer's inpatient medical-necessity criteria (InterQual / MCG).","If inpatient is supported, request a peer-to-peer review and/or submit a clinical appeal with the records.","If the downgrade is correct, rebill the encounter as observation/outpatient.","If the hospital's own utilization review changed the status before discharge, with the physician's agreement, bill the stay as outpatient with Condition Code 44 (Medicare).","Involve the Utilization Review team or physician advisor to support the appeal."],"keywords":["inpatient downgraded","level of care denial","observation downgrade","inpatient to outpatient","medical necessity inpatient","InterQual","MCG","Condition Code 44","utilization review denial","status change denial","two midnight rule"],"family":"Coverage & medical policy"},{"name":"Patient incarcerated / in custody","url":"https://x12.org/codes/remittance-advice-remark-codes","codes":["N103"],"denial_wording":"The claim is denied because records indicate the patient was incarcerated (in custody) on the date of service — the correctional facility or government entity in custody is generally responsible for the inmate's care, not the health plan.","summary":"Medicare and most payers will not pay for care given while a patient is incarcerated (in jail or prison), because the entity holding the person in custody is responsible for their medical costs. The claim denies as incarcerated / in custody (Medicare often cites remark N103). Resolution is to check the incarceration dates on file against the actual date of service: if the patient was not in custody on that date (or the record is wrong), appeal with proof; if they genuinely were, bill the correctional facility or responsible government entity instead of the health plan.","questions":["May I get the denial date?","What incarceration date range do you have on file for this patient?","If the incarceration dates on file are wrong, what proof do you need to overturn the denial (for example release documentation)?","Is there an appeal process for this, and what is the time frame?","What is the fax# or mailing address, and may I have the claim# and call ref#?"],"actions":["Confirm the patient's custody status and dates against the actual date of service.","If the patient was not in custody on the date of service (or the Social Security record is incorrect), appeal with documentation proving release/eligibility.","If the patient was incarcerated, redirect the bill to the correctional facility or responsible government entity.","Advise that, for Medicare, the beneficiary may need to correct their incarceration record with Social Security to prevent repeat denials.","Update the patient's account with the custody dates so future claims are handled correctly."],"keywords":["incarcerated patient","in custody denial","prisoner denial","N103","jail denial","patient in jail","correctional facility liable","incarceration dates","custody denial","inmate care not covered"],"family":"Liability & other"},{"name":"Claim underpaid (no line denied)","url":"","codes":[],"denial_wording":"The claim was paid, but for less than the expected contracted/allowed amount, and no individual CPT (procedure code) line was denied — the payment is simply short of the contract or fee schedule.","summary":"This is an underpayment, not a true denial: every line processed and nothing was denied, but the total paid is below what the contract or fee schedule says it should be. AR (Accounts Receivable) has to catch the variance, confirm the rate that should have applied, and recover the difference. Resolution is to compare the paid/allowed per CPT (procedure code) against the contracted rate or fee schedule, rule out any legitimate reduction (multiple-procedure, modifier, or bundling), and if it is genuinely short-paid, call the payer or file a reconsideration/appeal citing the contract rate.","questions":["What allowed amount did you apply per CPT, and which fee schedule or contract rate did you use?","Was the claim priced at the correct contracted rate?","Was any multiple-procedure or modifier reduction applied?","Is a reconsideration or project review available for underpayments, and what is the time frame?","What is the fax# or mailing address, and may I have the claim# and call ref#?"],"actions":["Compare the paid/allowed amount per line against the contracted rate or fee schedule and identify the underpaid lines and the dollar variance.","Rule out any legitimate reduction (multiple-procedure logic, modifier pricing, or bundling) before treating it as an underpayment.","If it is genuinely short-paid, call the payer to reprocess, or file a reconsideration/appeal citing the correct contract rate.","Escalate recurring underpayments from the same payer to the contracting / provider-relations team.","Document the expected vs. paid amount so the underpayment can be tracked and trended."],"keywords":["underpayment","underpaid claim","short paid","paid below contract","fee schedule underpayment","payment variance","allowed amount low","no CPT denied","reprocess for correct rate","contract rate not applied"],"family":"Status & payment"}];
